  `applicable_population` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'ADULT' COMMENT '适用人群: ADULT-成人, CHILD-儿童, ELDERLY-老人, PREGNANT-孕妇',
  `applicable_method` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'ORAL' COMMENT '适用用法: ORAL-口服, EXTERNAL-外用, INJECTION-注射',
  `applicable_form` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'DECOCTION' COMMENT '适用剂型: DECOCTION-汤剂, POWDER-散剂, PILL-丸剂',
  `effective_start` date DEFAULT NULL COMMENT '规则生效开始日期',
  `effective_end` date DEFAULT NULL COMMENT '规则生效结束日期',
