DROP TABLE IF EXISTS `his_raw_data`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `his_raw_data` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `request_no` varchar(64) NOT NULL COMMENT '请求流水号（唯一）',
  `institution_id` bigint DEFAULT NULL COMMENT '机构ID',
  `national_id` varchar(32) DEFAULT NULL COMMENT '患者身份证号',
  `patient_name` varchar(64) DEFAULT NULL COMMENT '患者姓名',
  `raw_request` text NOT NULL COMMENT 'HIS原始请求JSON',
  `process_status` varchar(20) NOT NULL DEFAULT 'SUCCESS' COMMENT '处理状态: SUCCESS/FAIL',
  `prescription_id` bigint DEFAULT NULL COMMENT '关联处方ID',
  `error_message` varchar(500) DEFAULT NULL COMMENT '失败原因',
  `created_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_request_no` (`request_no`),
  KEY `idx_national_id` (`national_id`),
  KEY `idx_institution_id` (`institution_id`),
  KEY `idx_created_time` (`created_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='HIS原始数据接收记录';
