--
-- Table structure for table `inventory`
--

DROP TABLE IF EXISTS `inventory`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `inventory` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '库存ID',
  `herb_id` int unsigned NOT NULL COMMENT '药材ID',
  `herb_name` varchar(100) DEFAULT NULL COMMENT '药材名称（快照）',
  `warehouse_id` bigint unsigned NOT NULL COMMENT '仓库ID',
  `supplier_id` bigint unsigned DEFAULT NULL COMMENT '供应商ID',
  `batch_no` varchar(50) DEFAULT NULL COMMENT '批次号',
  `quantity` decimal(10,2) DEFAULT '0.00' COMMENT '当前库存数量',
  `unit_price` decimal(10,2) DEFAULT NULL COMMENT '单价',
  `total_value` decimal(12,2) DEFAULT NULL COMMENT '总价值',
  `min_stock` decimal(10,2) DEFAULT '0.00' COMMENT '最低库存警戒线',
  `max_stock` decimal(10,2) DEFAULT NULL COMMENT '最高库存警戒线',
  `production_date` date DEFAULT NULL COMMENT '生产日期',
  `expiry_date` date DEFAULT NULL COMMENT '有效期',
  `storage_condition` varchar(200) DEFAULT NULL COMMENT '存储条件',
  `last_inbound_time` datetime DEFAULT NULL COMMENT '最后入库时间',
  `last_outbound_time` datetime DEFAULT NULL COMMENT '最后出库时间',
  `status` tinyint DEFAULT '1' COMMENT '状态: 1-正常, 0-冻结',
  `created_by` bigint unsigned DEFAULT NULL COMMENT '创建人',
  `updated_by` bigint unsigned DEFAULT NULL COMMENT '更新人',
  `created_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_herb_warehouse_supplier_batch` (`herb_id`,`warehouse_id`,`supplier_id`,`batch_no`),
  KEY `idx_herb_id` (`herb_id`),
  KEY `idx_warehouse_id` (`warehouse_id`),
  KEY `idx_supplier_id` (`supplier_id`),
  KEY `idx_status` (`status`),
  KEY `idx_expiry_date` (`expiry_date`),
  KEY `idx_created_by` (`created_by`),
  KEY `idx_updated_by` (`updated_by`),
  KEY `idx_inventory_herb_inbound_status` (`herb_id`,`last_inbound_time` DESC,`status`),
  KEY `idx_inventory_herb_supplier_status` (`herb_id`,`supplier_id`,`status`),
  KEY `idx_inventory_status` (`status`),
  CONSTRAINT `fk_inventory_created_by` FOREIGN KEY (`created_by`) REFERENCES `user` (`user_id`),
  CONSTRAINT `fk_inventory_herb` FOREIGN KEY (`herb_id`) REFERENCES `herbs` (`id`),
  CONSTRAINT `fk_inventory_supplier` FOREIGN KEY (`supplier_id`) REFERENCES `supplier` (`id`),
  CONSTRAINT `fk_inventory_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `user` (`user_id`),
  CONSTRAINT `fk_inventory_warehouse` FOREIGN KEY (`warehouse_id`) REFERENCES `warehouse` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1251 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='库存表';
/*!40101 SET character_set_client = @saved_cs_client */;

