--
-- Table structure for table `inventory_alert_config`
--

DROP TABLE IF EXISTS `inventory_alert_config`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `inventory_alert_config` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '配置ID',
  `herb_id` int unsigned NOT NULL COMMENT '药材ID',
  `warehouse_id` bigint unsigned NOT NULL COMMENT '仓库ID',
  `alert_type` varchar(20) NOT NULL COMMENT '告警类型: LOW_STOCK-低库存, HIGH_STOCK-高库存, EXPIRY-临期',
  `threshold_value` decimal(10,2) DEFAULT NULL COMMENT '阈值',
  `alert_status` tinyint DEFAULT '1' COMMENT '告警状态: 1-启用, 0-禁用',
  `notification_method` varchar(50) DEFAULT NULL COMMENT '通知方式: EMAIL-邮件, SMS-短信, SYSTEM-系统消息',
  `notification_target` varchar(200) DEFAULT NULL COMMENT '通知对象',
  `created_by` bigint unsigned DEFAULT NULL COMMENT '创建人',
  `updated_by` bigint unsigned DEFAULT NULL COMMENT '更新人',
  `created_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_herb_id` (`herb_id`),
  KEY `idx_warehouse_id` (`warehouse_id`),
  KEY `idx_alert_type` (`alert_type`),
  KEY `idx_alert_status` (`alert_status`),
  KEY `idx_created_by` (`created_by`),
  KEY `idx_updated_by` (`updated_by`),
  CONSTRAINT `fk_alert_config_created_by` FOREIGN KEY (`created_by`) REFERENCES `user` (`user_id`),
  CONSTRAINT `fk_alert_config_herb` FOREIGN KEY (`herb_id`) REFERENCES `herbs` (`id`),
  CONSTRAINT `fk_alert_config_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `user` (`user_id`),
  CONSTRAINT `fk_alert_config_warehouse` FOREIGN KEY (`warehouse_id`) REFERENCES `warehouse` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='库存告警配置表';
/*!40101 SET character_set_client = @saved_cs_client */;

