--
-- Table structure for table `inventory_alert_record`
--

DROP TABLE IF EXISTS `inventory_alert_record`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `inventory_alert_record` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `alert_config_id` bigint unsigned NOT NULL COMMENT '告警配置ID',
  `herb_id` int unsigned NOT NULL COMMENT '药材ID',
  `warehouse_id` bigint unsigned NOT NULL COMMENT '仓库ID',
  `alert_type` varchar(20) NOT NULL COMMENT '告警类型',
  `current_value` decimal(10,2) DEFAULT NULL COMMENT '当前值',
  `threshold_value` decimal(10,2) DEFAULT NULL COMMENT '阈值',
  `alert_level` varchar(20) DEFAULT NULL COMMENT '告警级别: INFO-提示, WARNING-警告, CRITICAL-严重',
  `alert_message` varchar(500) DEFAULT NULL COMMENT '告警信息',
  `is_handled` tinyint DEFAULT '0' COMMENT '是否已处理: 1-是, 0-否',
  `handled_by` bigint unsigned DEFAULT NULL COMMENT '处理人ID',
  `handled_time` datetime DEFAULT NULL COMMENT '处理时间',
  `handle_remark` varchar(500) DEFAULT NULL COMMENT '处理备注',
  `created_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '告警时间',
  PRIMARY KEY (`id`),
  KEY `idx_alert_config_id` (`alert_config_id`),
  KEY `idx_herb_id` (`herb_id`),
  KEY `idx_warehouse_id` (`warehouse_id`),
  KEY `idx_alert_type` (`alert_type`),
  KEY `idx_is_handled` (`is_handled`),
  KEY `idx_created_time` (`created_time`),
  KEY `fk_alert_record_handled_by` (`handled_by`),
  CONSTRAINT `fk_alert_record_config` FOREIGN KEY (`alert_config_id`) REFERENCES `inventory_alert_config` (`id`),
  CONSTRAINT `fk_alert_record_handled_by` FOREIGN KEY (`handled_by`) REFERENCES `user` (`user_id`),
  CONSTRAINT `fk_alert_record_herb` FOREIGN KEY (`herb_id`) REFERENCES `herbs` (`id`),
  CONSTRAINT `fk_alert_record_warehouse` FOREIGN KEY (`warehouse_id`) REFERENCES `warehouse` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='库存告警记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

