  `herb_id` int unsigned NOT NULL COMMENT '药材ID',
  `herb_name` varchar(100) DEFAULT NULL COMMENT '药材名称（快照）',
  `warehouse_id` bigint unsigned NOT NULL COMMENT '仓库ID',
  `supplier_id` bigint unsigned DEFAULT NULL COMMENT '供应商ID',
  `batch_no` varchar(50) DEFAULT NULL COMMENT '批次号',
  `transaction_type` varchar(20) NOT NULL COMMENT '交易类型: INBOUND-入库, OUTBOUND-出库, TRANSFER-调拨, RETURN-退货',
  `transaction_sub_type` varchar(50) DEFAULT NULL COMMENT '交易子类型: PURCHASE-采购入库, RETURN-退货入库, TRANSFER_IN-调拨入库, DISCOVERY-盘盈入库, SALE-销售出库, TRANSFER_OUT-调拨出库, LOSS-盘亏出库, DAMAGE-损耗出库',
  `quantity` decimal(10,2) NOT NULL COMMENT '数量',
  `unit_price` decimal(10,2) DEFAULT NULL COMMENT '单价',
  `total_amount` decimal(12,2) DEFAULT NULL COMMENT '总金额',
  `related_order_no` varchar(50) DEFAULT NULL COMMENT '关联订单号',
  `delivery_note_no` varchar(50) DEFAULT NULL COMMENT '随货清单编号',
  `operator_id` bigint unsigned DEFAULT NULL COMMENT '操作人ID',
  `operation_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  `reason` varchar(200) DEFAULT NULL COMMENT '出入库原因',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `created_by` bigint unsigned DEFAULT NULL COMMENT '创建人',
  `updated_by` bigint unsigned DEFAULT NULL COMMENT '更新人',
  `created_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_transaction_no` (`transaction_no`),
  KEY `idx_herb_id` (`herb_id`),
  KEY `idx_warehouse_id` (`warehouse_id`),
  KEY `idx_supplier_id` (`supplier_id`),
  KEY `idx_transaction_type` (`transaction_type`),
  KEY `idx_operation_time` (`operation_time`),
  KEY `idx_operator_id` (`operator_id`),
  KEY `idx_related_order_no` (`related_order_no`),
  KEY `idx_created_by` (`created_by`),
  KEY `idx_updated_by` (`updated_by`),
  CONSTRAINT `fk_transaction_created_by` FOREIGN KEY (`created_by`) REFERENCES `user` (`user_id`),
  CONSTRAINT `fk_transaction_herb` FOREIGN KEY (`herb_id`) REFERENCES `herbs` (`id`),
  CONSTRAINT `fk_transaction_operator` FOREIGN KEY (`operator_id`) REFERENCES `user` (`user_id`),
  CONSTRAINT `fk_transaction_supplier` FOREIGN KEY (`supplier_id`) REFERENCES `supplier` (`id`),
  CONSTRAINT `fk_transaction_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `user` (`user_id`),
  CONSTRAINT `fk_transaction_warehouse` FOREIGN KEY (`warehouse_id`) REFERENCES `warehouse` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=173 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='出入库记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

