DROP TABLE IF EXISTS `medical_record`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `medical_record` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '病历唯一标识',
  `record_no` varchar(50) NOT NULL COMMENT '病历号/就诊流水号 (如 MR202403260001)',
  `patient_id` bigint unsigned NOT NULL COMMENT '患者全局ID',
  `institution_record_id` bigint unsigned NOT NULL COMMENT '机构档案ID',
  `institution_id` bigint unsigned NOT NULL COMMENT '就诊机构ID',
  `visit_type` enum('OUTPATIENT','INPATIENT','EMERGENCY','FOLLOW_UP') NOT NULL DEFAULT 'OUTPATIENT' COMMENT '就诊类型: 门诊, 住院, 急诊, 随访',
  `visit_time` datetime NOT NULL COMMENT '就诊时间',
  `department` varchar(100) DEFAULT NULL COMMENT '就诊科室',
  `chief_complaint` text COMMENT '主诉',
  `present_illness_history` text COMMENT '现病史',
  `past_medical_history_snapshot` text COMMENT '过往病史快照',
  `allergy_history_snapshot` text COMMENT '过敏史快照',
  `patient_info_snapshot` text COMMENT '患者基本信息快照 (JSON格式，存储前端传来的 key=value 数据)',
  `physical_exam` text COMMENT '体格检查',
  `primary_diagnosis` text COMMENT '初步诊断',
  `treatment_opinion` text COMMENT '诊疗意见',
  `attending_physician_id` bigint unsigned DEFAULT NULL COMMENT '接诊医生ID',
  `record_status` enum('DRAFT','COMPLETED','SIGNED','ARCHIVED') DEFAULT 'DRAFT' COMMENT '病历状态: 草稿, 完成, 已签名, 已归档',
  `created_by` bigint unsigned DEFAULT NULL COMMENT '创建人',
  `updated_by` bigint unsigned DEFAULT NULL COMMENT '更新人',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_record_no` (`record_no`),
  KEY `idx_patient_id` (`patient_id`),
  KEY `idx_institution_record` (`institution_record_id`),
  KEY `idx_institution_id` (`institution_id`),
  KEY `idx_visit_time` (`visit_time`),
  KEY `idx_attending_physician` (`attending_physician_id`),
  KEY `idx_record_status` (`record_status`),
  CONSTRAINT `fk_medical_record_doctor` FOREIGN KEY (`attending_physician_id`) REFERENCES `user` (`user_id`),
  CONSTRAINT `fk_medical_record_institution` FOREIGN KEY (`institution_id`) REFERENCES `organization` (`org_id`),
  CONSTRAINT `fk_medical_record_institution_record` FOREIGN KEY (`institution_record_id`) REFERENCES `patient_institution_record` (`id`),
  CONSTRAINT `fk_medical_record_patient` FOREIGN KEY (`patient_id`) REFERENCES `patient` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=36 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='病历/就诊记录主表';
/*!40101 SET character_set_client = @saved_cs_client */;

