DROP TABLE IF EXISTS `organization`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `organization` (
  `org_id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '机构ID',
  `org_code` varchar(50) NOT NULL COMMENT '机构编码',
  `org_name` varchar(200) NOT NULL COMMENT '机构名称',
  `org_type` varchar(50) NOT NULL COMMENT '机构类型编码 (如: CORE_HOSPITAL, HOSPITAL, COMMUNITY. 逻辑含义由应用层定义)',
  `parent_id` bigint unsigned DEFAULT NULL COMMENT '父机构ID',
  `level_path` varchar(500) DEFAULT NULL COMMENT '层级路径(如: /1/5/10/)',
  `level` int DEFAULT '1' COMMENT '机构层级',
  `contact_person` varchar(50) DEFAULT NULL COMMENT '联系人',
  `contact_phone` varchar(20) DEFAULT NULL COMMENT '联系电话',
  `address` varchar(500) DEFAULT NULL COMMENT '机构地址',
  `status` tinyint DEFAULT '1' COMMENT '状态: 0-禁用，1-启用',
  `is_system` tinyint DEFAULT '0' COMMENT '是否系统内置机构(如：总院): 0-否，1-是',
  `prescription_review_fee` decimal(10,2) DEFAULT '0.00' COMMENT '审方费',
  `dispensing_fee` decimal(10,2) DEFAULT '0.00' COMMENT '配药费',
  `decoction_fee` decimal(10,2) DEFAULT '0.00' COMMENT '煎药费',
  `logistics_fee` decimal(10,2) DEFAULT '0.00' COMMENT '物流费',
  `created_by` bigint unsigned DEFAULT NULL COMMENT '创建人',
  `updated_by` bigint unsigned DEFAULT NULL COMMENT '更新人',
  `created_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`org_id`),
  UNIQUE KEY `uk_org_code` (`org_code`),
  KEY `idx_org_type` (`org_type`),
  KEY `idx_parent_id` (`parent_id`),
  KEY `idx_status` (`status`),
  KEY `idx_created_by` (`created_by`),
  KEY `idx_updated_by` (`updated_by`),
  CONSTRAINT `fk_organization_creator` FOREIGN KEY (`created_by`) REFERENCES `user` (`user_id`),
  CONSTRAINT `fk_organization_parent` FOREIGN KEY (`parent_id`) REFERENCES `organization` (`org_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_organization_updater` FOREIGN KEY (`updated_by`) REFERENCES `user` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='组织机构表';
