--
-- Table structure for table `patient_institution_record`
--

DROP TABLE IF EXISTS `patient_institution_record`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `patient_institution_record` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '档案ID',
  `patient_id` bigint unsigned NOT NULL COMMENT '患者全局ID',
  `institution_id` bigint unsigned NOT NULL COMMENT '机构ID',
  `local_patient_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '本院患者编号(如M20240001)',
  `contact_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '本院登记的联系电话',
  `contact_phone_verified` tinyint DEFAULT '0' COMMENT '联系电话是否已验证: 0-未验证, 1-已验证',
  `wechat_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '本院登记的微信号',
  `emergency_contact` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '紧急联系人',
  `emergency_contact_relation` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '紧急联系人关系',
  `emergency_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '紧急联系电话',
  `delivery_address` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '配送地址 (煎配核心字段)',
  `allergy_history` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '过敏史(本院记录)',
  `past_medical_history` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '过往病史（如手术史、重大疾病史等）',
  `chronic_disease` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '慢性病史(本院记录)',
  `height` decimal(5,2) DEFAULT NULL COMMENT '身高(cm)(最近记录)',
  `weight` decimal(5,2) DEFAULT NULL COMMENT '体重(kg)(最近记录)',
  `pregnancy_status` tinyint DEFAULT '0' COMMENT '妊娠状态: 0-无/未知,1-早期,2-中期,3-晚期,4-哺乳期',
  `liver_function` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '肝功能状态',
  `renal_function` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '肾功能状态',
  `primary_physician_id` bigint unsigned DEFAULT NULL COMMENT '主诊/责任医生ID',
  `patient_type` enum('OUTPATIENT','INPATIENT') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'OUTPATIENT' COMMENT '患者类型: 门诊, 住院',
  `archive_status` enum('ACTIVE','INACTIVE','ARCHIVED') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'ACTIVE' COMMENT '档案状态: 活跃, 未激活, 已归档',
  `first_visit_date` date DEFAULT NULL COMMENT '首次就诊日期',
  `last_visit_date` date DEFAULT NULL COMMENT '最近就诊日期',
  `data_source` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'SELF' COMMENT '数据来源: SELF-自建, HIS-医院系统, PLATFORM-平台导入',
  `created_by` bigint unsigned DEFAULT NULL COMMENT '建档人',
  `created_by_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '建档人姓名(冗余)',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '建档时间',
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_institution_local_no` (`institution_id`,`local_patient_no`),
  UNIQUE KEY `uk_patient_institution` (`patient_id`,`institution_id`),
  KEY `idx_patient_id` (`patient_id`),
  KEY `idx_institution_id` (`institution_id`),
  KEY `idx_primary_physician` (`primary_physician_id`),
  KEY `idx_contact_phone` (`contact_phone`),
  KEY `idx_last_visit_date` (`last_visit_date`),
  CONSTRAINT `fk_record_institution` FOREIGN KEY (`institution_id`) REFERENCES `organization` (`org_id`),
  CONSTRAINT `fk_record_patient` FOREIGN KEY (`patient_id`) REFERENCES `patient` (`id`),
  CONSTRAINT `fk_record_primary_doctor` FOREIGN KEY (`primary_physician_id`) REFERENCES `user` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='机构患者档案表';
/*!40101 SET character_set_client = @saved_cs_client */;

