DROP TABLE IF EXISTS `permission`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `permission` (
  `perm_id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '权限ID',
  `perm_code` varchar(100) NOT NULL COMMENT '权限编码',
  `perm_name` varchar(100) NOT NULL COMMENT '权限名称',
  `perm_type` varchar(20) DEFAULT 'MENU' COMMENT '权限类型: MENU-菜单, BUTTON-按钮, API-接口, DATA-数据',
  `parent_id` bigint unsigned DEFAULT NULL COMMENT '父权限ID',
  `route_path` varchar(255) DEFAULT NULL COMMENT '前端路由地址',
  `component` varchar(255) DEFAULT NULL COMMENT '前端组件路径',
  `resource_path` varchar(500) DEFAULT NULL COMMENT '资源路径(接口URL)',
  `external_link` varchar(500) DEFAULT NULL COMMENT '外部链接',
  `active_path` varchar(500) DEFAULT NULL COMMENT '激活路径（用于菜单高亮）',
  `icon` varchar(100) DEFAULT NULL COMMENT '图标',
  `badge_text` varchar(20) DEFAULT NULL COMMENT '徽章文本',
  `sort_order` int DEFAULT '0' COMMENT '排序',
  `is_enabled` tinyint DEFAULT '1' COMMENT '是否启用',
  `is_cache` tinyint DEFAULT '0' COMMENT '是否缓存页面',
  `is_visible` tinyint DEFAULT '1' COMMENT '是否在菜单中显示',
  `is_embed` tinyint DEFAULT '0' COMMENT '是否内嵌',
  `is_affix` tinyint DEFAULT '0' COMMENT '是否固定标签',
  `is_hide_tag` tinyint DEFAULT '0' COMMENT '是否隐藏标签',
  `is_fullpage` tinyint DEFAULT '0' COMMENT '是否全屏页面',
  `description` varchar(500) DEFAULT NULL COMMENT '权限描述',
  `created_by` bigint unsigned DEFAULT NULL COMMENT '创建人',
  `updated_by` bigint unsigned DEFAULT NULL COMMENT '更新人',
  `created_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`perm_id`),
  UNIQUE KEY `uk_perm_code` (`perm_code`),
  KEY `idx_parent_id` (`parent_id`),
  KEY `idx_perm_type` (`perm_type`),
  KEY `fk_permission_user_c` (`created_by`),
  KEY `fk_permission_user_u` (`updated_by`),
  CONSTRAINT `fk_permission_parent` FOREIGN KEY (`parent_id`) REFERENCES `permission` (`perm_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_permission_user_c` FOREIGN KEY (`created_by`) REFERENCES `user` (`user_id`),
  CONSTRAINT `fk_permission_user_u` FOREIGN KEY (`updated_by`) REFERENCES `user` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=132 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='系统权限表(增强版)';
