--
-- Table structure for table `prescription`
--

DROP TABLE IF EXISTS `prescription`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `prescription` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '处方唯一标识',
  `prescription_no` varchar(50) NOT NULL COMMENT '处方号 (业务流水号，如 RP202403260001)',
  `medical_record_id` bigint unsigned NOT NULL COMMENT '关联病历ID',
  `patient_id` bigint unsigned NOT NULL COMMENT '患者全局ID',
  `institution_record_id` bigint unsigned NOT NULL COMMENT '机构档案ID',
  `institution_id` bigint unsigned NOT NULL COMMENT '开具机构ID',
  `prescriber_id` bigint unsigned NOT NULL COMMENT '开方医生ID',
  `prescriber_name` varchar(100) NOT NULL COMMENT '开方医生姓名',
  `prescribe_time` datetime NOT NULL COMMENT '开方时间',
  `prescription_type` enum('DECOCTION','POWDER','PILL','GRANULE','EXTERNAL') DEFAULT 'DECOCTION' COMMENT '处方剂型: 汤剂, 散剂, 丸剂, 颗粒剂, 外用',
  `service_type` enum('SELF','DISPENSING_ONLY','DECOCTION') NOT NULL DEFAULT 'SELF' COMMENT '服务类型: SELF-自煎/自配, DISPENSING_ONLY-代配, DECOCTION-代煎',
  `dosage_days` int NOT NULL DEFAULT '1' COMMENT '用药天数',
  `dosage_times_per_day` int NOT NULL DEFAULT '2' COMMENT '每日服用次数',
  `total_packages` int NOT NULL DEFAULT '1' COMMENT '总剂数/包数',
  `is_urgent` tinyint DEFAULT '0' COMMENT '是否加急: 0-普通, 1-加急',
  `decoction_method` text COMMENT '特殊煎法要求',
  `package_requirement` varchar(200) DEFAULT NULL COMMENT '代配打包要求',
  `usage_method` text COMMENT '用法用量描述',
  `delivery_address` text COMMENT '配送地址',
  `delivery_phone` varchar(20) DEFAULT NULL COMMENT '配送联系电话',
  `prescription_status` enum('DRAFT','SUBMITTED','CHECKING','APPROVED','REJECTED','DISPENSING','DISPENSED','CANCELLED') DEFAULT 'DRAFT' COMMENT '处方状态',
  `checker_id` bigint unsigned DEFAULT NULL COMMENT '审方人ID',
  `checker_name` varchar(100) DEFAULT NULL COMMENT '审方人姓名',
  `check_time` datetime DEFAULT NULL COMMENT '审方时间',
  `check_result` enum('PASS','REJECT','MODIFY') DEFAULT NULL COMMENT '审方结果',
  `check_opinion` text COMMENT '审方意见',
  `ai_suggestion` text COMMENT 'AI审方建议',
  `audit_trail` json DEFAULT NULL COMMENT '审核追踪记录',
  `herb_total_amount` decimal(10,2) DEFAULT '0.00' COMMENT '药材总价（元）',
  `service_fee` decimal(10,2) DEFAULT '0.00' COMMENT '服务费（元）',
  `review_fee` decimal(10,2) DEFAULT '0.00' COMMENT '审方费用（元）',
  `dispensing_fee` decimal(10,2) DEFAULT '0.00' COMMENT '配药费用（元）',
  `decoction_fee` decimal(10,2) DEFAULT '0.00' COMMENT '煎药费用（元）',
  `delivery_fee` decimal(10,2) DEFAULT '0.00' COMMENT '配送费（元）',
  `total_amount` decimal(10,2) DEFAULT '0.00' COMMENT '处方总金额（元）',
  `created_by` bigint unsigned DEFAULT NULL COMMENT '创建人',
  `updated_by` bigint unsigned DEFAULT NULL COMMENT '更新人',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_prescription_no` (`prescription_no`),
  KEY `idx_medical_record_id` (`medical_record_id`),
  KEY `idx_patient_id` (`patient_id`),
  KEY `idx_institution_id` (`institution_id`),
  KEY `idx_prescriber_id` (`prescriber_id`),
  KEY `idx_prescribe_time` (`prescribe_time`),
  KEY `idx_prescription_status` (`prescription_status`),
  KEY `idx_checker_id` (`checker_id`),
  KEY `idx_service_type` (`service_type`),
  KEY `fk_prescription_institution_record` (`institution_record_id`),
  KEY `idx_prescription_inst_status_service_created` (`institution_id`,`prescription_status`,`service_type`,`created_at`),
  KEY `idx_prescription_status_service_created` (`prescription_status`,`service_type`,`created_at`),
  KEY `idx_prescription_created_at` (`created_at`),
  CONSTRAINT `fk_prescription_institution` FOREIGN KEY (`institution_id`) REFERENCES `organization` (`org_id`),
  CONSTRAINT `fk_prescription_institution_record` FOREIGN KEY (`institution_record_id`) REFERENCES `patient_institution_record` (`id`),
  CONSTRAINT `fk_prescription_medical_record` FOREIGN KEY (`medical_record_id`) REFERENCES `medical_record` (`id`),
  CONSTRAINT `fk_prescription_patient` FOREIGN KEY (`patient_id`) REFERENCES `patient` (`id`),
  CONSTRAINT `fk_prescription_prescriber` FOREIGN KEY (`prescriber_id`) REFERENCES `user` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=73 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='处方主表';
/*!40101 SET character_set_client = @saved_cs_client */;

