--
-- Table structure for table `prescription_detail`
--

DROP TABLE IF EXISTS `prescription_detail`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `prescription_detail` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '详情ID',
  `prescription_id` bigint unsigned NOT NULL COMMENT '处方ID',
  `herb_id` int unsigned NOT NULL COMMENT '药材ID',
  `herb_name` varchar(100) NOT NULL COMMENT '药材名称',
  `dosage_per_package` decimal(10,2) NOT NULL COMMENT '每剂/包用量',
  `dosage_unit` varchar(20) DEFAULT 'g' COMMENT '用量单位',
  `total_dosage` decimal(10,2) NOT NULL COMMENT '总用量',
  `special_note` varchar(200) DEFAULT NULL COMMENT '特殊注明',
  `seq_no` int NOT NULL DEFAULT '1' COMMENT '排序序号',
  `unit_price` decimal(10,2) DEFAULT '0.00' COMMENT '单价（元/单位）',
  `line_total` decimal(10,2) DEFAULT '0.00' COMMENT '行小计（元）',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_prescription_id` (`prescription_id`),
