--
-- Table structure for table `prescription_order`
--

DROP TABLE IF EXISTS `prescription_order`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `prescription_order` (
  `order_id` bigint NOT NULL AUTO_INCREMENT COMMENT '订单ID',
  `order_no` varchar(50) NOT NULL COMMENT '订单编号',
  `patient_id` bigint NOT NULL COMMENT '患者ID',
  `prescription_id` bigint NOT NULL COMMENT '处方ID',
  `org_id` bigint NOT NULL COMMENT '机构ID',
  `production_task_id` bigint DEFAULT NULL COMMENT '生产任务ID（关联生产模块）',
  `outbound_batch_no` varchar(50) DEFAULT NULL COMMENT '出库批次号（关联 inventory_transaction.batch_no，同一次出库共享同一批次号）',
  `entrust_type` tinyint DEFAULT '1' COMMENT '委托方式：0-自煎/自配 1-代煎 2-代配',
  `course_days` int DEFAULT NULL COMMENT '疗程天数',
  `usage_dosage` varchar(200) DEFAULT NULL COMMENT '用法用量',
  `total_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '订单总金额',
  `order_status` varchar(20) NOT NULL DEFAULT 'PENDING' COMMENT '订单状态：PENDING-待确认 CONFIRMED-已确认 PREPARING-配药中 COMPLETED-已完成 CANCELLED-已取消',
  `production_no` varchar(50) DEFAULT NULL COMMENT '生产编号',
  `production_method` varchar(50) DEFAULT NULL COMMENT '生产方式',
  `audit_user_id` bigint DEFAULT NULL COMMENT '审核人员ID',
  `audit_time` datetime DEFAULT NULL COMMENT '审核时间',
  `production_user_id` bigint DEFAULT NULL COMMENT '生产人员ID',
  `production_time` datetime DEFAULT NULL COMMENT '生产时间',
  `quality_user_id` bigint DEFAULT NULL COMMENT '质检人员ID',
  `quality_time` datetime DEFAULT NULL COMMENT '质检时间',
  `delivery_company` varchar(100) DEFAULT NULL COMMENT '物流公司',
  `delivery_tracking_no` varchar(100) DEFAULT NULL COMMENT '物流单号',
  `delivery_address` varchar(500) DEFAULT NULL COMMENT '收货地址',
  `delivery_phone` varchar(20) DEFAULT NULL COMMENT '配送联系电话',
  `delivery_note_no` varchar(50) DEFAULT NULL COMMENT '随货清单编号',
  `delivery_status` varchar(20) DEFAULT 'PENDING' COMMENT '配送状态：PENDING-待发货 SHIPPING-配送中 DELIVERED-已送达',
  `confirm_time` datetime DEFAULT NULL COMMENT '确认时间',
  `complete_time` datetime DEFAULT NULL COMMENT '完成时间',
  `cancel_time` datetime DEFAULT NULL COMMENT '取消时间',
  `cancel_reason` varchar(500) DEFAULT NULL COMMENT '取消原因',
  `created_by` bigint DEFAULT NULL COMMENT '创建人',
  `created_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` bigint DEFAULT NULL COMMENT '更新人',
  `updated_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_deleted` tinyint DEFAULT '0' COMMENT '是否删除：0-否 1-是',
  PRIMARY KEY (`order_id`),
  UNIQUE KEY `uk_order_no` (`order_no`),
  KEY `idx_patient_id` (`patient_id`),
  KEY `idx_prescription_id` (`prescription_id`),
  KEY `idx_org_id` (`org_id`),
  KEY `idx_production_task_id` (`production_task_id`),
  KEY `idx_order_status` (`order_status`),
  KEY `idx_created_time` (`created_time`),
  KEY `idx_outbound_batch_no` (`outbound_batch_no`)
) ENGINE=InnoDB AUTO_INCREMENT=29 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='处方订单表';
/*!40101 SET character_set_client = @saved_cs_client */;

