--
-- Table structure for table `prescription_template`
--

DROP TABLE IF EXISTS `prescription_template`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `prescription_template` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '模板ID',
  `template_no` varchar(50) NOT NULL COMMENT '模板编号 (如 TMP202606010001)',
  `template_name` varchar(200) NOT NULL COMMENT '模板名称 (如"四物汤")',
  `org_id` bigint unsigned NOT NULL COMMENT '所属机构ID',
  `category` varchar(50) DEFAULT NULL COMMENT '分类 (如"补血方"/"清热方"/"自定义")',
  `description` text COMMENT '模板描述/功效说明',
  `prescription_type` enum('DECOCTION','POWDER','PILL','GRANULE','EXTERNAL') DEFAULT 'DECOCTION' COMMENT '处方剂型: DECOCTION-汤剂, POWDER-散剂, PILL-丸剂, GRANULE-颗粒剂, EXTERNAL-外用',
  `service_type` enum('SELF','DISPENSING_ONLY','DECOCTION') DEFAULT 'SELF' COMMENT '服务类型: SELF-自煎/自配, DISPENSING_ONLY-代配, DECOCTION-代煎',
  `dosage_days` int DEFAULT '7' COMMENT '默认用药天数',
  `dosage_times_per_day` int DEFAULT '2' COMMENT '默认每日服用次数',
  `decoction_method` text COMMENT '默认煎法要求 (如先煎、后下、包煎等描述)',
  `usage_method` text COMMENT '默认用法用量 (如"饭后温服")',
  `applicable_symptoms` text COMMENT '适用症状描述',
  `contraindications` text COMMENT '禁忌症',
  `is_public` tinyint DEFAULT '0' COMMENT '是否机构内公开: 0-仅创建人可见, 1-机构内所有医生可见',
  `created_by` bigint unsigned DEFAULT NULL COMMENT '创建人ID',
  `status` enum('ACTIVE','INACTIVE') DEFAULT 'ACTIVE' COMMENT '状态: ACTIVE-启用, INACTIVE-禁用',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_template_no` (`template_no`),
  KEY `idx_org_id` (`org_id`),
  KEY `idx_category` (`category`),
  KEY `idx_created_by` (`created_by`),
  KEY `idx_is_public` (`is_public`),
  KEY `idx_status` (`status`),
  CONSTRAINT `fk_template_organization` FOREIGN KEY (`org_id`) REFERENCES `organization` (`org_id`)
) ENGINE=InnoDB AUTO_INCREMENT=43 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='处方模板主表';
/*!40101 SET character_set_client = @saved_cs_client */;

