DROP TABLE IF EXISTS `prescription_template_detail`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `prescription_template_detail` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '详情ID',
  `template_id` bigint unsigned NOT NULL COMMENT '模板ID',
  `herb_id` int unsigned NOT NULL COMMENT '药材ID',
  `herb_name` varchar(100) NOT NULL COMMENT '药材名称(冗余)',
  `dosage_per_package` decimal(10,2) NOT NULL COMMENT '每剂/包用量',
  `dosage_unit` varchar(20) DEFAULT 'g' COMMENT '用量单位',
  `special_note` varchar(200) DEFAULT NULL COMMENT '特殊注明 (如"打碎"、"带心"、"先煎"、"后下")',
  `seq_no` int NOT NULL DEFAULT '1' COMMENT '排序序号',
  PRIMARY KEY (`id`),
  KEY `idx_template_id` (`template_id`),
  KEY `idx_herb_id` (`herb_id`),
  CONSTRAINT `fk_template_detail_herb` FOREIGN KEY (`herb_id`) REFERENCES `herbs` (`id`),
  CONSTRAINT `fk_template_detail_template` FOREIGN KEY (`template_id`) REFERENCES `prescription_template` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=98 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='处方模板详情表';
