DROP TABLE IF EXISTS `production_task`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `production_task` (
  `task_id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '任务ID',
  `task_no` varchar(50) NOT NULL COMMENT '任务编号 (业务流水号，如 PT202403260001)',
  `prescription_id` bigint unsigned NOT NULL COMMENT '关联处方ID',
  `order_id` bigint unsigned DEFAULT NULL COMMENT '关联订单ID（预留字段）',
  `production_status` enum('PENDING','IN_PRODUCTION','QUALITY_CHECK','COMPLETED','CANCELLED') DEFAULT 'PENDING' COMMENT '生产状态: PENDING-待生产, IN_PRODUCTION-生产中, QUALITY_CHECK-质检中, COMPLETED-已完成, CANCELLED-已取消',
  `production_method` varchar(50) DEFAULT NULL COMMENT '生产方式: DECOCTION-代煎, DISPENSING-代配, POWDER-散剂, PILL-丸剂, GRANULE-颗粒剂',
  `auditor_id` bigint unsigned DEFAULT NULL COMMENT '审核人员ID',
  `auditor_name` varchar(100) DEFAULT NULL COMMENT '审核人员姓名',
  `audit_time` datetime DEFAULT NULL COMMENT '审核时间',
  `audit_opinion` text COMMENT '审核意见',
  `producer_id` bigint unsigned DEFAULT NULL COMMENT '生产人员ID',
  `producer_name` varchar(100) DEFAULT NULL COMMENT '生产人员姓名',
  `production_start_time` datetime DEFAULT NULL COMMENT '生产开始时间',
  `production_end_time` datetime DEFAULT NULL COMMENT '生产完成时间',
  `quality_checker_id` bigint unsigned DEFAULT NULL COMMENT '质检人员ID',
  `quality_checker_name` varchar(100) DEFAULT NULL COMMENT '质检人员姓名',
  `quality_check_time` datetime DEFAULT NULL COMMENT '质检时间',
  `quality_result` enum('PASS','REJECT','MODIFY') DEFAULT NULL COMMENT '质检结果: PASS-合格, REJECT-不合格, MODIFY-需修改',
  `quality_opinion` text COMMENT '质检意见',
  `remark` text COMMENT '备注',
  `created_by` bigint unsigned DEFAULT NULL COMMENT '创建人',
  `updated_by` bigint unsigned DEFAULT NULL COMMENT '更新人',
  `created_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后更新时间',
  PRIMARY KEY (`task_id`),
  UNIQUE KEY `uk_task_no` (`task_no`),
  KEY `idx_prescription_id` (`prescription_id`),
  KEY `idx_order_id` (`order_id`),
  KEY `idx_production_status` (`production_status`),
  KEY `idx_auditor_id` (`auditor_id`),
  KEY `idx_producer_id` (`producer_id`),
  KEY `idx_quality_checker_id` (`quality_checker_id`),
  KEY `idx_created_time` (`created_time`),
  CONSTRAINT `fk_production_task_prescription` FOREIGN KEY (`prescription_id`) REFERENCES `prescription` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='生产任务主表';
/*!40101 SET character_set_client = @saved_cs_client */;

