/*!40000 ALTER TABLE `preparation` DISABLE KEYS */;
INSERT INTO `preparation` VALUES (1,'Z00001','跌打除痹膏','6g/贴','自主加工','2贴/封','湘药制备字Z20180010000','活血祛瘀、温经通络、消肿止痛。用于软组织劳损及骨折中后期局部肿痛不消或陈旧性骨折复发肿痛证属瘀血或寒凝血瘀者。','以上二十三味，冰片研成细粉，龙血竭、醋乳香、醋没药、儿茶、肉桂粉碎成细粉，与上述冰片细粉配研，过筛，混匀；除红花、透骨草外，其余生川乌等十五味，与麻油6000g置锅内浸渍24小时后，炸至药材表面枯黄，加入红花、透骨草继续炸至药材内部焦黄，去渣，滤过，炼油至滴水成珠，加入铅丹1850～1900g，搅匀，收膏，浸膏，取膏，用文火熔化，加入上述细粉，搅匀，分摊于牛皮纸上，即得。','新邵县中医医院','黑膏药',NULL,'新邵制剂室',2000.00000000,0.00000000,19.85000000,0.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(2,'Z00002','黄药粉','2kg/袋','自主加工','2kg/袋','湘药制备字Z20210511000','清热解毒，活血止痛，散瘀消肿。用于跌打损伤，血瘀气滞所至肌肤红、肿、热、痛。','以上十九味，粉碎成细粉，过筛，混匀，分装，即得。','邵阳市中医医院','散剂',NULL,'邵阳制剂室',34.00000000,0.00000000,0.00000000,0.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(3,'Z00003','安络小皮伞酒','500ml/瓶','自主加工','每瓶装500ml','湘药制备字Z20210508000','通络活血，止痛。用于类风湿关节炎、风湿性关节炎，坐骨神经痛，三叉神经痛，跌打损伤，骨折疼痛等。','取安络小皮伞，粉碎成最粗粉，置酒剂浸泡罐中，加入75%的食用酒精325L，浸泡4～5日，加纯化水至50万ml，隔日循环一次，每次2小时，提取15日。滤过，滤液静置7日，取上清液，加纯化水至50万ml，混匀，即得。','邵阳市中医医院','酒剂',NULL,'邵阳制剂室',1000.00000000,0.00000000,0.00000000,0.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(4,'Z00004','天元胶囊','24粒/盒','自主加工','每粒装0.4g','湘药制字Z20080569','理气活血，化瘀散结。可用于乳腺、子宫、卵巢等各种良性肿瘤证属气滞血瘀者。','以上十三味，取醋延胡索、重楼粉碎成细粉；其余醋柴胡等十一味药材加水煎煮三次，每次2小时，滤过，合并滤液，滤液浓缩至相对密度1.30(60℃)的浸膏；放冷，加乙醇使含醇量为70%，充分搅拌，静置24小时，取上清液回收乙醇，减压浓缩至','邵阳市中医医院','胶囊剂',NULL,'邵阳制剂室',6250.00000000,0.00000000,0.00000000,0.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(5,'Z00005','益肾壮骨胶囊','24粒/盒','自主加工','每粒装0.4g。','湘药制字Z20080570','补益肝肾，强筋壮骨，活血通络。用于跌打损伤所致骨折、脱位、筋伤后期证属肝肾亏虚者','以上十四味，白芍、制何首乌、地龙、土鳖虫等四味粉碎成细粉。其余杜仲','邵阳市中医医院','胶囊剂',NULL,'邵阳制剂室',8333.00000000,0.00000000,0.00000000,0.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(6,'Z00006','平瘤康胶囊','24粒/盒','自主加工','每粒装0.3g。','湘药制备字Z2021555000','软坚散结，活血化瘀，用于各种肿瘤属血瘀痰凝证。','以七味，浙贝母、僵蚕、山慈菇、蜈蚣、全蝎五味粉碎成粗粉；再与醋乳香、醋没药混合，粉碎成细粉，装入胶囊，制成1000粒，即得','邵阳市中医医院','胶囊剂',NULL,'邵阳制剂室',8333.00000000,0.00000000,0.00000000,0.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(7,'Z00007','杏桔止咳合剂','100ml/瓶','自主加工','每瓶装100ml','湘药制备字Z20210556000','解表散寒，止咳化痰。用于急性支气管炎、慢性支气管炎急性发作证属风寒者。','以上十味，加水煎煮三次，每次1.5小时，滤过，合并滤液，浓缩至相对密度约为1.03（60℃）的浸膏，加入蔗糖60kg、羟苯乙酯90g，搅拌使溶解，放冷，滤过，加水至30万ml，灌封，灭菌，即得','邵阳市中医医院','合剂',NULL,'邵阳制剂室',3000.00000000,0.00000000,0.00000000,0.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(8,'Z00008','生津玉液合剂','250ml/瓶','自主加工','每瓶装250ml','湘药制备字Z20210553000','养阴生津，清热解毒。用于放疗、化疗所致的口腔炎，以及急、慢性咽喉','以上十四味，加水煎煮三次，每次2小时，滤过，滤液合并，浓缩至相对密度约为1.03（60℃）的浸膏，加入蔗糖60kg、羟苯乙酯90g，搅拌使溶解，滤过，加水至30万ml，灌封，灭菌，即得','邵阳市中医医院','合剂',NULL,'邵阳制剂室',1200.00000000,0.00000000,0.00000000,0.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(9,'Z00009','复方赤丹红止痛合剂','250ml/瓶','自主加工','每瓶装250ml','湘药制备字Z20210557000','活血祛瘀，行气通络。用于骨折、脱位、筋伤之初期证属气滞血瘀者','以上十五味，加水煎煮三次，每次2小时，滤过，合并滤液，浓缩至相对密度约为1.03（60℃）的浸膏，加入蔗糖60kg、羟苯乙酯90g，搅拌使溶解，滤过，加水至30万ml，灌封，灭菌，即得','邵阳市中医医院','合剂',NULL,'邵阳制剂室',1200.00000000,0.00000000,0.00000000,0.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(10,'Z00010','七味消毒合剂','100ml/瓶','自主加工','每瓶装100ml','湘药制备字Z2021554000','清热解毒，凉血活血。用于痈肿疮毒热毒蕴结，症见局部红肿、热痛者','以上七味，金银花、野菊花两味加水蒸馏提取芳香水，备用；蒸馏后的水溶液另器收集；药渣与其余蒲公英等五味，加水煎煮三次，每次1小时，滤过，合并滤液与蒸馏后的水溶液，浓缩至相对密度为1.03（60℃）的浸膏，加入蔗糖60kg、羟苯乙酯60g，搅拌使溶解，加入芳香水，混匀，滤过，滤液加水至30万ml，灌封，115℃灭菌30分钟，即得。','邵阳市中医医院','合剂',NULL,'邵阳制剂室',3000.00000000,0.00000000,0.00000000,0.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(11,'Z00011','抗骨刺增生合剂','250ml/瓶','自主加工','每瓶装250ml','湘药制备字Z20210510000','益肾养血，活络止痛。用于肾虚络阻的致颈椎、腰椎、腰腿痛','制法：以上十六味，加水煎煮三次，每次1.5小时，滤过，合并滤液，浓缩至相对密度为1.03（40℃）的浸膏，加入蔗糖60kg、羟苯乙酯90g，搅拌使溶解，加水至30万ml，滤过，灌封，灭菌，即得','邵阳市中医医院','合剂',NULL,'邵阳制剂室',1200.00000000,0.00000000,0.00000000,0.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(12,'Z00012','跌打胶囊','每粒装0.35g','自主加工','12粒/板*2板/盒','湘制B20210047','活血理气、消肿止痛。用于急性软组织挫伤及骨折早期血瘀气滞，症见局部瘀肿疼痛，活动不利等。','以上十四味，延胡索干燥，粉碎成细粉，备用；醋乳香、醋没药干燥，加入二氧化硅适量，混合，粉碎成细粉，备用；其余当归（归尾）等十一味加水煎煮二次，每次1.5小时，合并煎液，滤过，滤液浓缩至相对密度为1.25～1.30（60℃）的稠膏，加入延胡索细粉，混合，减压干燥，粉碎成细粉，再加入醋乳香、醋醋没，混匀，制粒，干燥，加入硬脂酸镁适量，混匀，装入胶囊，制成1000粒，即得。','新邵县中医医院','胶囊剂',NULL,'新邵制剂室',16667.00000000,0.00000000,44.06000000,0.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(13,'Z00013','止痛胶囊','每粒装0.3g','自主加工','12粒/板*2板/盒','湘制B20200034','活血止痛。用于跌打损伤所致瘀血肿痛。','以上四味，三七干燥，粉碎成细粉，备用；醋乳香、醋没药干燥，加二氧化硅适量，混合，粉碎成细粉，备用；延胡索粉碎成最粗粉，用60%乙醇浸泡24小时，加热回流提取二次，每次2小时，合并提取液，滤过，滤液回收乙醇，浓缩至相对密度为1.25～1.30(60℃)的稠膏，加入上述三七细粉，混合，干燥，粉碎成细粉，与上述醋乳香、醋没药细粉混合，混匀，制成颗粒，干燥，加入硬脂酸镁适量，混匀，装入胶囊，制成1000粒，即得。','新邵县中医医院','胶囊剂',NULL,'新邵制剂室',12500.00000000,0.00000000,44.97000000,0.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(14,'Z00014','续断接骨胶囊','每粒装0.38g','自主加工','12粒/板*2板/盒','湘制B20200035','益气养血，活血通络，续经接骨。用于骨折中期瘀血未尽，气血已伤之证。','以上十四味，酒续断、龙血竭粉碎成细粉，备用；其余黄芪等十二味加水煎煮二次，每次2小时，合并煎液，滤过，滤液浓缩至相对密度为1.30(60℃)的稠膏，干燥，粉碎，过筛，与上述细粉混匀，装入胶囊，制成1000粒，即得。','新邵县中医医院','胶囊剂',NULL,'新邵制剂室',16667.00000000,0.00000000,44.68000000,0.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(15,'Z00015','壮骨胶囊','每粒装0.3g','自主加工','12粒/板*2板/盒','湘制B20210046','补肾壮骨。用于骨折后期，肾精亏虚之骨质疏松、骨折迟缓愈合。','以上十一味，鹿茸、酒续断干燥，分别粉碎成细粉，备用；其余淫羊藿等九味，加水煎煮二次，每次2小时，合并煎液，滤过，滤液浓缩至相对密度为1.25～1.30(60℃)的稠膏，加入上述细粉，混匀，减压干燥，粉碎成细粉，制粒，干燥，加入硬脂酸镁适量，混匀，装入胶囊，制成1000粒，即得。','新邵县中医医院','胶囊剂',NULL,'新邵制剂室',16667.00000000,0.00000000,57.62000000,0.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(16,'Z00016','蒲芪益肝丸','120g/瓶','委托加工','120g/瓶','湘药制字Z20080666','清热解毒，祛湿健脾，滋补肝肾。用于慢性乙肝证属湿热瘀滞兼脾肾虚者。','以上十四味，粉碎成细粉，过筛，混匀。每100g细粉加炼蜜100～120g制成小蜜丸，即得。','安化县中医医院','丸剂',NULL,'新邵制剂室',600.00000000,39.17700000,46.09000000,27.65000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(17,'Z00017','疏通颗粒','8g/袋*10袋/盒','委托加工','8g/包','湘药制备字Z20190182003','本品活血祛瘀，消肿止痛。用于软组织损伤、骨折所致的疼痛、淤血、肿胀的治疗。','以上十一味，乳香、没药和三七50~60℃干燥，混合粉碎成细粉，过筛，备用；其余八味，加水提取两次，第一次加8倍水煎煮1.5小时；第二次加6倍水提取1小时，过滤，滤液减压浓缩（60~70℃，-0.06~-0.08Mpa）至相对密度约为1.15～1.20(60℃热测)的稠膏，加入上述细粉及糊精适量，制粒，制成约1000g，即得。','长沙洪山正骨医院','颗粒剂',NULL,'德康制药',3000.00000000,25.80000000,0.00000000,25.80000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(18,'Z00018','清热利湿通淋颗粒','8g/袋*10袋/盒','委托加工','8g/袋','湘药制备字20210530001','清热凉血，利湿通淋。用于下焦湿热兼肾虚血瘀所致尿频、余沥不尽、或伴见神疲乏力、腰膝疲软等；前列腺炎、前列腺肥大见上述证候者。','以上生地黄等十味，加水煎煮二次，第一次煎煮1.5小时，第二次煎煮1小时，合并煎液，滤过，滤液浓缩至相对密度为1.25～1.30（60℃）的稠膏，干燥，粉碎，加入糊精适量混匀，制粒，干燥，制成1000g，即得。','长沙楚元中西医结合医院','颗粒剂',NULL,'新邵制剂室',500.00000000,29.40000000,0.00000000,29.40000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(19,'Z00019','清热明目颗粒','6g/袋*10袋/盒','委托加工','6g/包','湘药制备字Z20210463001','本品退翳明目、清热解毒，活血化瘀。用于火热上攻所致翳障，伴羞明流泪、沙涩不适。角膜云翳、角膜血管翳见上述症候。','以上二十四味，加水提取两次，第一次加8倍水煎煮1.5小时；第二次加6倍水提取1小时，过滤，合并两次滤液减压浓缩(60~70℃，-0.06~-0.08Mpa)至相对密度约为1.15～1.20(60℃热测)的稠膏，真空干燥(温度60~70℃，真空度-0.06~-0.08MPa，)，得干膏，粉碎，干膏粉加糊精适量，混匀，90%乙醇制粒，干燥，整粒，制成约1000g，即得。','津市市中医医院','颗粒剂',NULL,'新邵制剂室',2000.00000000,29.67500000,59.35000000,29.67500000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(20,'Z00020','杞地明目颗粒','8g/袋*10袋/盒','委托加工','8g/包','湘药制备字Z20200191001','本品滋阴明目，安神养心，补肾益精，增强视力，用于肾真阴不足所致腰膝酸软，五心烦热、眩晕耳鸣、潮热盗汗等，青少年近视见上述证候者。','以上十五味药，加水提取两次，第一次加8倍水煎煮1.5小时；第二次加6倍水提取1小时，过滤，合并两次滤液减压浓缩（60~70℃，-0.06~-0.08Mpa）至相对密度约为1.25～1.30(60℃热测)的稠膏，真空干燥（60~70℃，-0.06~-0.08Mpa），得干膏，粉碎，得干膏粉，加麦芽糊精、二氧化硅适量，混匀，95%乙醇制粒，干燥，整粒，制成约1000g，包装即得。','津市市中医医院','颗粒剂',NULL,'新邵制剂室',1000.00000000,34.24000000,68.48000000,34.24000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(21,'Z00021','桑参养阴颗粒','8g/袋*10袋/盒','委托加工','8g/袋','湘药制备字Z20210531001','益气养阴，清热生津，化瘀通络。临床用于气阴不足、肺胃津伤、热盛伤津所致多饮、多尿、多食等症之Ⅱ型糖尿病及其引发血管神经病变的治疗。','以上七味，人参、三七分别取半，混合粉碎成细粉，过筛，备用；余下与桑叶等五味加水煎煮两次，第一次煎煮1.5小时，第二次煎煮1小时，合并煎液，滤过，滤液浓缩至相对密度为1.25～1.30（60℃）的稠膏，干燥，粉碎，加入上述细粉及糊精适量，制粒，干燥，制成1000g，即得。','长沙楚元中西医结合医院','颗粒剂',NULL,'新邵制剂室',1000.00000000,41.40000000,0.00000000,41.40000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(22,'Z00022','软肝丸','100g/瓶','委托加工','100g/瓶','湘药制字Z20060070','清热解毒，祛湿止痒。用于真菌、滴虫及细菌性阴道炎、外阴瘙痒、宫颈炎和各种皮炎、皮肤瘙痒、痱子、体股癣等证属湿热者。','以上十味，除薄荷素油外，其余蛇床子等九味加水煎煮二次，每次45分钟，合并煎液，滤过，滤液加氢氧化钠调节pH值至7～9，滤过，离心，滤液浓缩至相对密度约为1.01（40℃）的清膏，加入羟苯乙酯2g与薄荷素油0.6ml，加水至1000ml，搅匀，即得。','岳阳市中心医院','丸剂',NULL,'新邵制剂室',1500.00000000,45.70000000,45.70000000,36.56000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(23,'Z00023','阴炎净洗液','200mI/瓶','委托加工','200ml/瓶','','','','岳阳市中心医院','洗剂',NULL,'邵阳制剂室',2000.00000000,19.20000000,19.20000000,15.36000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(24,'Z00024','银花清热洗液','120ml/瓶','委托加工','120ml/瓶','湘药制备字Z20210539002','清热燥湿、杀虫止痒，用于外阴瘙痒、湿疹、皮炎、肛瘘及痔疮术后等证属湿热者。','以上八药味，除白矾外，其他药味第一次加8倍量水，浸泡30min后，煎煮1.5小时，煎液滤过，药渣加6倍量水煎煮1小时，煎液滤过；煎液，浓缩至约相对密度1.05～1.010（60℃），加入白矾使溶解，静置12小时，滤过，加入防腐剂（山梨酸钾0.2%，羟苯乙酯0.2%，g/V）使溶解，调整体积至1000ml，灌装，灭菌，即得。','安乡县人民医院','洗剂',NULL,'邵阳制剂室',3333.00000000,13.10000000,0.00000000,13.10000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(25,'Z00025','归芍养血祛风胶囊','0.42g/粒*100粒/瓶','委托加工','每粒装0.42g','湘药制字Z20130964','养血祛风，润燥止痒。用于血虚风燥所致皮肤瘙痒、干燥、粗糙、肥厚、脱屑或泛发红色丘疹，舌淡，脉细或弦细等症。慢性湿疹、神经性皮炎及皮肤瘙痒症见上述症状者。','以上十三味药材，阿胶粉碎成细粉，备用；其余生地黄等十二味，加水浸泡1小时，煎煮2.5小时，第二、三次各2小时，煎液滤过，合并滤液，减压浓缩至相对密度为1.25～1.30(60℃)的稠膏，干燥，粉碎成细粉,加入上述阿胶细粉及适量淀粉，混匀，制粒，装入胶囊，制成1000粒，即得。','长沙鸿业皮肤病专科医院','胶囊剂',NULL,'新邵制剂室',5000.00000000,40.00000000,0.00000000,40.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(26,'Z00026','荆翘祛风清热颗粒','8g/袋*10袋/盒','委托加工','8g/袋','湘药制备字Z20180052000','清热解毒，祛风止痒。用于风热所致的皮肤瘙痒，起风团或斑，遇凉则缓，遇热则甚，或皮肤灼热、心烦、口干苦，舌尖边红，苔薄黄，脉浮数等症；荨麻疹、湿疹及皮肤瘙痒症见上述证候者。','以上十二味，连翘等十一味药第一次加水煎煮至沸时加入黄芩，煎煮2.5小时，第二、三次各2小时，滤过，合并滤液，减压浓缩至相对密度为1.25～1.30(60℃)的稠膏，干燥，粉碎成细粉,加入适量糊精，混匀，以3%聚维酮K30乙醇溶液制粒，干燥，制成1000g，即得。','长沙鸿业皮肤病专科医院','颗粒剂',NULL,'新邵制剂室',1500.00000000,29.00000000,0.00000000,29.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(27,'Z00027','苓茵湿热颗粒','8g/袋*10包','委托加工','8g/袋','湘药制备字Z20180054000','清热利湿，解毒止痒。用于湿热浸淫肌肤所致的皮肤瘙痒、起红色斑疹、渗出粘稠，或伴皮肤灼热，心烦，口渴，尿黄，便秘，舌红苔黄腻，脉滑等症；湿疹见上述证候者。','以上十一味药材，除黄芩外，其余土茯苓等十味，加水煎煮至沸时加入黄芩，煎煮2小时，第二、三次各1.5小时，滤过，合并滤液，滤液减压浓缩至相对密度为1.25～1.30(60℃)的稠膏，干燥，粉碎成细粉,与适量可溶性淀粉混匀，以3%聚维酮K30乙醇溶液制成颗粒，干燥，制成1000g，即得。','长沙鸿业皮肤病专科医院','颗粒剂',NULL,'新邵制剂室',2000.00000000,29.00000000,0.00000000,29.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(28,'Z00028','知黄凉血颗粒','8g/袋*10袋/盒','委托加工','8g/袋','湘药制备字Z20180053000','清热凉血、祛风止痒。用于血热生风所致皮肤瘙痒，起红疹或紫色斑疹，灼热痒痛，口渴，尿黄，便结，舌红，脉数等症，湿疹、皮肤瘙痒症有上述症状者。','以上十二味药材，水牛角浓缩粉外另置，其余生地黄等十一味，第一次加水浸泡30分钟，煎煮2小时，第二次1.5小时，滤过，合并滤液，滤液浓缩至相对密度为1.25～1.30(60℃)的稠膏，干燥，粉碎成细粉,加入与水牛角浓缩粉及适量糊精混匀，以3%聚维酮K30乙醇溶液制成颗粒，干燥，制成1000g，即得。','长沙鸿业皮肤病专科医院','颗粒剂',NULL,'新邵制剂室',2000.00000000,29.00000000,0.00000000,29.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(29,'Z00029','参萸降糖胶囊','0.5g*100粒/瓶','委托加工','每粒装0.5g（每粒含盐酸二甲双胍62mg）','湘药制字Z20060120','益气生津、和营通络，用于气阴两虚，见咽干口燥、倦怠乏力、口渴喜饮、气短懒言、舌红少津、手足麻木、脉细数等症，II型糖尿病见上述证候者。','以上十味，葛根、红参，肉桂、三七、山茱萸粉碎成细粉，备用；除盐酸二甲双胍外，其余白芍等四味加水提取二次，每次2小时，合并煎液，滤过，滤液浓缩至相对密度为1.30〜1.35(55C)的浸膏，干燥，加入上述细粉,混匀，再按等量递增法加入盐酸二甲双胍，混匀，加淀粉适量，制粒，装胶囊，约制成1000粒，即得。','湘潭糖尿病医院','胶囊剂',NULL,'新邵制剂室',2000.00000000,43.00000000,0.00000000,14.80000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(30,'Z00030','三参降糖胶囊','0.45g*100粒/瓶','委托加工','每粒装0.45g','湘药制字Z20060119','养阴清热、益气化瘀。用于燥热内盛，气虚血瘀,见口渴多饮、心烦、易饥、倦怠、舌红或暗红、舌尖边有瘀斑或瘀点等症，Ⅱ型糖尿病见上述症候者。','以上十一味，粉碎成细粉，过筛，灭菌，备用；加入淀粉73.2g，混合均匀，装入胶囊，制成1000粒，即得。','湘潭糖尿病医院','胶囊剂',NULL,'新邵制剂室',2000.00000000,37.00000000,0.00000000,15.80000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(31,'Z00031','柏参颗粒','15g/袋×9袋/盒','委托加工','15g/袋','湘药制备字Z20210369001','清热利湿、消肿止痛。用于肛肠疾病证属湿热者。','以上十一味，加水煎煮二次，第一次加6倍量水，浸泡30min，煎煮2小时，第二次加4倍量水煎煮1小时，合并煎液，滤过，滤液减压浓缩至相对密度为1.25(60℃测)的清膏，干燥成干浸膏，粉碎成干浸膏粉；另取糊精适量，加入上述干浸膏粉，混匀，用75%乙醇制软材，12目筛制粒，80℃干燥，放冷，12目筛整粒，约制成1000g，即得。','益阳市第一中医医院','颗粒剂',NULL,'新邵制剂室',1000.00000000,62.50000000,175.90000000,62.50000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(32,'Z00032','路路通酊','60ml/瓶','委托加工','60ml/瓶','湘药制备字Z20220577001','祛风除湿，活血化瘀，通络止痛。用于风湿瘀阻所致的痹病和瘀血阻络所致的跌打损伤，症见关节疼痛、肿胀麻木、腰膝酸软、屈伸不利，或局部疼痛肿胀、活动功能障碍；骨性关节炎、腰肌劳损、软组织损伤、骨折见上述证候者。','以上十四味，冰片研细；其余路路通等十三味粉碎成粗粉，混匀，用75%乙醇作溶剂，浸渍48小时后，缓缓渗漉，收集渗漉液，加入冰片，溶解，混匀，滤过，加75%乙醇调至1000ml，搅匀，静置，滤过，分装，即得。','益阳市第一中医医院','酊剂',NULL,'新邵制剂室',2000.00000000,8.00000000,0.00000000,8.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(33,'Z00033','荆芥止咳合剂','每瓶装150ml','委托加工','每瓶装150ml','湘药制备字Z20220688000','疏风散寒，宣肺化痰，清热解毒。用于肺阴不足导致的咳嗽咯痰或干咳无痰、胸闷气促、咽部红肿、发热等，成人或小儿急、慢性支气管炎见上述证候者。','以上十三味，加水煎煮二次，第一次1.5小时，第二次1小时，合并煎液，滤过，滤液浓缩至相对密度为1.10～1.15（60℃）的清膏，静置，取上清液，滤过，滤液加入蔗糖、苯甲酸钠适量，加水至1000ml，搅匀，滤过，分装，即得。','岳阳市中心医院','合剂',NULL,'邵阳制剂室',1000.00000000,56.53000000,0.00000000,45.22400000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(34,'Z00034','利胆化石合剂','每瓶装200ml','委托加工','每瓶装200ml','湘药制备字Z20220687000','清热利湿，利胆排石。用于肝胆湿热所致的上腹隐痛或胀满不适、口苦、恶心呕吐、大便秘结、舌红苔黄腻、脉弦数或弦滑，胆囊炎、胆石症、排石术后见上述证候者。','以上八味，加水煎煮两次，第一次1.5小时，第二次1小时，合并煎液，滤过，滤液浓缩至相对密度为1.05～1.10（60℃）的清膏，滤过，滤液加入三氯蔗糖、苯甲酸钠适量使溶解，加水至1000ml，搅匀，即得。','岳阳市中心医院','合剂',NULL,'邵阳制剂室',1500.00000000,38.84800000,48.56000000,38.84800000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(35,'Z00035','益气养阴合剂','200ml/瓶','委托加工','每瓶装200ml','湘药制备字Z20220686000','益气养阴，软坚散结。用于气阴两虚所致神疲乏力、头晕耳鸣、少气懒言或恶心呕吐、慢性疲劳、心悸失眠等，久病虚损或手术、放化疗后见上述证候者。','以上十一味，加水煎煮两次，第一次1.5小时，第二次1.0小时，合并煎液，滤过，滤液浓缩至相对密度为1.05～1.10（60℃）的清膏，滤过，滤液加入三氯蔗糖、苯甲酸钠适量使溶解，加水至1000ml，搅匀，即得。','岳阳市中心医院','合剂',NULL,'邵阳制剂室',1500.00000000,46.48000000,0.00000000,37.18400000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(36,'Z00036','金黄宣肺合剂','每瓶装 200ml','委托加工','每瓶装200ml','湘药制备字Z20220696000','清热化痰，宣肺止咳。用于风热袭肺证所致的咳嗽、发热、口渴、便干尿黄、胸膈满闷、咳嗽咽痛等，急性支气管炎、慢性支气管炎急性发作见上述症状者。','以上十二味，加水煎煮两次，第一次2.0小时，第二次1.5小时，合并煎液，滤过，滤液浓缩至相对密度为1.15～1.20（60℃）的清膏，滤过，滤液加入三氯蔗糖、苯甲酸钠适量，加水至1000ml，搅匀，即得。','安乡县人民医院','合剂',NULL,'邵阳制剂室',1000.00000000,19.90000000,0.00000000,19.90000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(37,'Z00037','胃和胶囊','0.3g*60粒/瓶','委托加工','每粒装0.3g','湘药制备字Z20180025000','活血化瘀，行气止痛。用于胃十二指肠溃疡，慢性胃炎气滞血瘀所致脘腹胀满作痛，食欲不振，消化不良，恶心呕吐，嗳气反酸等症。','以上九味，粉碎成细粉，过筛，干燥，装胶囊1000粒，即得。','怀化鹤城区风湿病研究所附属医院','胶囊剂',NULL,'邵阳制剂室',5000.00000000,11.00000000,0.00000000,11.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(38,'Z00038','类风湿胶囊','0.3g*60粒/瓶','委托加工','每粒装0.3g','湘药制备字Z20180035000','补肝益肾，补精益髓、活血通络、散寒止痛。用于风湿性关节炎、类风湿关节炎、强直性脊椎炎、红斑狼疮、痛风、证属肾虚风寒湿阻络者。','以上二十九味，干燥，粉碎成细粉，灭菌，装入胶囊，制成1000粒，分装，即得。','怀化鹤城区风湿病研究所附属医院','胶囊剂',NULL,'邵阳制剂室',20000.00000000,16.50000000,0.00000000,16.50000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(39,'Z00039','骨痹胶囊','0.3g*60粒/瓶','委托加工','每粒装0.3g','湘药制备字Z20180033000','\"补肾健骨，舒筋活血，消肿止痛。用于颈椎、胸椎、腰 椎、四肢关节骨骨关节病引起的颈肩腰腿病等证属肾虚血瘀者。\"','以上二十三味，粉碎成细粉，装入胶囊，制成1000粒，即得。','怀化鹤城区风湿病研究所附属医院','胶囊剂',NULL,'邵阳制剂室',10000.00000000,14.60000000,0.00000000,14.60000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(40,'Z00040','麻痛消胶囊','0.3g*60粒/瓶','委托加工','每粒装0.3g','湘药制备字Z20180027000','舒筋通络，活血止痛。用于瘀血阻络所致肢体拘挛，手足麻木，腰腿酸痛。','以上九味，干燥，粉碎成细粉，加淀粉30g制粒。混匀，装入胶囊，制成1000粒。即得。','怀化鹤城区风湿病研究所附属医院','胶囊剂',NULL,'邵阳制剂室',10000.00000000,11.00000000,0.00000000,11.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(41,'Z00041','补钙壮骨胶囊','0.3g*60粒/瓶','委托加工','每粒装0.3g','湘药制备字Z20180031000','滋补肝肾，强腰健骨。用于预防和治疗缺钙所致的骨质疏松症。','以上七味，混匀，粉碎成80目粉，过筛，装入胶囊，分装，即得。','怀化鹤城区风湿病研究所附属医院','胶囊剂',NULL,'邵阳制剂室',10000.00000000,11.20000000,0.00000000,11.20000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(42,'Z00042','甘砂丸','7g/袋*9袋/盒','委托加工','每袋装7g','湘药制备字Z20220608000','清热化湿，理气和胃。用于湿热中阻所致的胃痛，症见胃脘疼痛、脘中灼热、痞胀不适、嗳气反酸；慢性胃炎、胃溃疡见上述证候者。','以上九味,粉碎成细粉,过筛,灭菌,混匀,加玉米淀粉浆适量,制丸,干燥,制成约1000g,即得.','澧县中医医院','丸剂',NULL,'新邵制剂室',2000.00000000,13.33000000,0.00000000,13.33000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(43,'Z00043','元胡通络丸','每袋装9g','委托加工','每盒装9袋','湘药制备字Z20220606000','活血行气,祛瘀通络,消肿止痛。用于瘀血阻络所致的痹病,症见肢体疼痛、肿胀麻木、腰腿疼痛、活动受限；骨性关节炎、腰肌劳损见上述证候者。','以上十三味,粉碎成细粉,过筛,灭菌,混匀,加水适量,制丸,干燥,制成约10OOg,即得。','澧县中医医院','丸剂',NULL,'新邵制剂室',4000.00000000,17.23000000,0.00000000,17.23000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(44,'Z00044','玄红止痛酊','50ml/瓶','委托加工','每瓶装50ml','湘药制备字Z20220599000','祛风除湿，通络止痛。用于风寒湿闭阻，瘀血阻络所致的痹病，症见四肢麻木、腰腿酸痛、筋脉拘挛、关节不利；风湿性关节炎、急慢性颈肩腰腿痛见上述证候者。亦用于瘀血阻络所致的跌打损伤，症见伤处肿胀疼痛、活动跟你受限；软组织损伤、捩伤见上述证候者。','以上十二味，冰片研细；其余醋延胡索等十一味粉碎成粗粉，混匀，用75%乙醇浸渍7日，滤过，加入冰片，溶解，混匀，加75%乙醇调至1000ml，搅匀，静置，滤过，分装，即得。','长沙颐而康颈肩腰腿痛医院','酊剂',NULL,'新邵制剂室',5000.00000000,9.90000000,0.00000000,9.90000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(45,'Z00045','双金排石颗粒','8g/袋*6袋/盒','委托加工','每袋装8g','湘药制备字Z20220645000','清热利尿，排石通淋。用于湿热下注所致排尿费力、尿频、尿急、尿痛，泌尿系统结石见上述症状者。','以上十味，加水煎煮二次，第一次煎煮1.5小时，第二次煎煮1.0小时，合并煎液，滤过，浓缩至相对密度约为1.25～1.30（60℃）的稠膏，干燥，粉碎，加入糊精适量，混匀，制粒，干燥，制成1000g，即得。','安乡县人民医院','颗粒剂',NULL,'新邵制剂室',2000.00000000,23.84000000,0.00000000,23.84000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(46,'Z00046','解毒软坚颗粒','8g/袋*9袋/盒','委托加工','每袋装8g','湘药制备字Z20220646000','清热解毒，软坚化瘀。用于气滞血瘀、热毒蕴结所致的肝癌、胃癌、肺癌、食道癌等多种肿瘤的治疗和手术、放、化疗后的辅助治疗。','以上十二味，加水煎煮两次，第一次1.5小时，第二次1.0小时，合并煎液，滤过，浓缩至相对密度约为1.25～1.30（60℃）的稠膏，干燥，粉碎，加入糊精适量，混匀，制粒，干燥，制成1000g，即得。','安乡县人民医院','颗粒剂',NULL,'新邵制剂室',1000.00000000,40.22000000,0.00000000,40.22000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(47,'Z00047','黄苓养阴颗粒','6g*9袋/盒','委托加工','每袋装6g','湘药制备字Z20220650000','益气养阴，活血化瘀，清热解毒。用于气阴两虚，瘀毒互结所致神疲乏力、口燥咽干、面色无华、手足心热、腰膝酸软、腰痛固定或刺痛，肾功能不全、慢性肾炎、慢性肾衰竭见上述症状者。','以上十一味，加水煎煮两次，第一次1.5小时，第二次1.0小时，合并煎液，滤过，滤液浓缩至相对密度约为1.25～1.30（60℃）的稠膏，干燥，粉碎，加入糊精适量，混匀，制粒，干燥，制成1000g，即得。','安乡县人民医院','颗粒剂',NULL,'新邵制剂室',1000.00000000,14.70000000,0.00000000,14.70000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(48,'Z00048','白花清热颗粒','8g*6袋/盒','委托加工','每袋装8g','湘药制备字Z20220647000','清热解毒，祛湿止带。用于湿热蕴结所致下腹、腰骶部胀痛、带下量多、色黄质稠、或伴低热起伏、神疲乏力、小便黄赤、舌苔黄腻，慢性盆腔炎、宫颈炎等妇科炎症见上述症状者。','以上十二味，加水煎煮二次，第一次煎煮1.5小时，第二次煎煮1.0小时，合并煎液，滤过，滤液浓缩至相对密度约为1.25～1.30（60℃）的稠膏，干燥，粉碎，加入糊精适量，混匀，制粒，干燥，制成1000g，即得。','安乡县人民医院','颗粒剂',NULL,'新邵制剂室',1000.00000000,14.04000000,0.00000000,14.04000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(49,'Z00049','三痹颗粒','15g*6袋/盒','委托加工','每袋装15g','湘药制备字Z20230774000','益气活血，除湿通络，补益肝肾。用于肝肾气血不足、外感风寒湿邪所致的腰膝关节疼痛、屈伸不利、肢体麻木、筋脉挛急等，风湿类风湿性关节炎、骨性关节炎、创伤性关节炎、腰椎间盘突出、腰椎管狭窄、软组织挫伤、产后风湿等见上述症状者。','以上十五味，加水煎煮两次，第一次1.5小时，第二次1.0小时，滤过，合并滤液，滤液浓缩至相对密度约为1.25～1.30（60℃）的稠膏，干燥，粉碎，加入糊精、三氯蔗糖适量，混匀，制粒，干燥，制成约1000g，即得。','娄底市中医医院','颗粒剂',NULL,'新邵制剂室',2000.00000000,29.50000000,0.00000000,29.50000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(50,'Z00050','健脾和胃颗粒','8g/袋*6袋/盒','委托加工','每袋装8g','湘药制备字Z20230817000','健脾和胃，理气止痛。用于脾胃虚弱，运化失职，气机不畅所致的脘腹胀满、疼痛、纳呆、返酸、烧心、呕吐、呃逆等，慢性胃炎、胃溃疡见上述症状者。','以上十四味，加水煎煮两次，第一次1.5小时，第二次1小时，合并煎液，滤过，滤液浓缩至相对密度约为1.25～1.30（60℃）的稠膏，干燥，粉碎，加入糊精及三氯蔗糖适量，混匀，制粒，干燥，制成约1000g，即得。','娄底市中医医院','颗粒剂',NULL,'新邵制剂室',2000.00000000,17.10000000,0.00000000,17.10000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(51,'Z00051','活血止痛颗粒','9g/袋*9袋/盒','委托加工','每袋装9g','湘药制备字Z20230773000','活血化瘀，消肿行气止痛。用于气滞血瘀所致的局部瘀血肿胀、筋骨拘挛疼痛、屈伸不利，舌质紫暗有瘀斑，脉弦涩等，跌打损伤见上述症状者。','以上十六味，加水煎煮二次，第一次煎煮1.5小时，第二次煎煮1.0小时，合并煎液，滤过，浓缩至相对密度约为1.25～1.30（60℃）的稠膏，干燥，粉碎，加入糊精、三氯蔗糖适量，混匀，制粒，干燥，制成1000g，即得。','娄底市中医医院','颗粒剂',NULL,'新邵制剂室',5000.00000000,21.85000000,0.00000000,21.85000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(52,'Z00052','紫黄膏','20g/支','委托加工','20g/支','湘药制备字Z20230732000','清热解毒，止痛生肌。用于烧烫伤属火毒炽盛证，程度较轻的烧伤（Ⅰ°或浅Ⅱ°）症见局部皮肤色红或起水疱疼痛。亦可用于褥疮、糖尿病足。','\" 以上八味，取大黄、黄芩、黄柏、苦参、白芷、地榆加入麻油1100g，搅匀，浸渍24小时，缓慢加热至150℃～200℃，文火保持油温，时时搅拌，炸至白芷枯黄，下降油温至90℃～100℃，续加入紫草（加入前稍用水润湿），搅拌均匀，保持油温约1小时；200目滤布过滤，除去药渣。取药油，控制油温90℃～100℃，另加蜂蜡、羊毛脂适量（每100g药膏加蜂蜡6～8g、羊毛脂2g）溶化；待温度降至约50℃～60℃时，加入冰片（粉碎，过80目筛），搅匀，即得。\"','湘乡市尚如湖铁医院','贴膏',NULL,'新邵制剂室',5000.00000000,17.00000000,0.00000000,17.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(53,'Z00053','健脾养血丸','每瓶装60g','委托加工','每瓶装60g','湘药制备字Z20220614000','益气健脾，补血养心。用于气血不足，心脾两虚所致的心悸、不寐，症见面色无华、心悸气短、神疲乏力、失眠多梦；贫血、神经衰弱见上述证候者。','以上七味，粉碎成细粉，过筛，灭菌，混匀，加水适量，制丸，干燥，制成约1000g,即得。','岳阳市中医医院','丸剂',NULL,'新邵制剂室',2000.00000000,20.30000000,0.00000000,20.30000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(54,'Z00054','丹楂降脂丸','每瓶装60g','委托加工','每瓶装60g','湘药制备字Z20220617000','\"化浊降脂，活血祛瘀。用于痰浊阻滞型高脂血症，症见头重体困、形体肥胖、胸闷泛恶、大便干燥。 \"','以上十一味，粉碎成细粉，过筛，灭菌，混匀，加淀粉浆适量，制丸，干燥，制成约1000g,即得。','岳阳市中医医院','丸剂',NULL,'新邵制剂室',1000.00000000,19.00000000,0.00000000,19.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(55,'Z00055','健脾护肝胶囊','0.4g*60粒/瓶','委托加工','每粒装0.4g','湘药制字Z20080554','疏肝解郁，渗湿理脾，清热解毒，软坚散结。用于慢性肝炎证属肝郁脾虚者。','以上十五味，茯苓的90g和湘曲粉碎成细粉，备用；鳖甲加水煎煮二次，每次2小时，合并煎液，滤过，滤液备用；当归、砂仁、白术、郁金加水蒸馏提取挥发油，备用；蒸馏后的水溶液另器收集；药渣、剩余茯苓与其余柴胡等九味加水煎煮三次，第一次2小时，第二次1.5小时，第三次1小时，合并煎液，滤过，滤液与上述蒸馏后的水溶液合并，浓缩至约1000ml,加乙醇至含醇量达60%,静置24小时，取上清液滤过，滤渣用90%乙醇约3000ml洗涤2次，滤过，洗液与滤液合并，回收乙醇并浓缩至相对密度为1.25(40℃)的浸膏，加入上述鳖甲煎液，浓缩至相对密度为1.45(60℃)的浸膏，加入上述细粉，混匀，低温干燥，粉碎，制粒，喷入上述挥发油，混匀，制成1000粒，即得。','祁阳市中医医院','胶囊剂',NULL,'邵阳制剂室',800.00000000,21.46800000,0.00000000,21.46800000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(56,'Z00056','新伤跌打胶囊','0.35g*60粒/瓶','委托加工','每粒装0.35g','湘药制字Z20060126','活血散瘀，消肿止痛。用于跌打损伤，筋伤骨折初期，瘀血肿痛。','以上十二味，三七、延胡索、大黄粉碎成细粉，备用；当归、川芎加水蒸馏提取挥发油，备用；蒸馏后的水溶液另器收集；药渣与其余桃仁等七味加水煎煮三次，第一次2小时，第二次1.5小时，第三次1时，合并煎液，滤过，滤液与上述蒸馏后的水溶液合并，浓缩至约1000ml,加乙醇使含醇量达65%,静置24小时，取上清液，滤过，滤渣用90%乙醇约3000ml分2次洗涤，滤过，洗液与上述滤液合并，回收乙醇并浓缩至相对密度为1.40(60℃)的浸膏，加入上述细粉，混匀，干燥，粉碎，制粒，喷入上述挥发油，装入胶囊，制成1000粒，即得。','祁阳市中医医院','胶囊剂',NULL,'邵阳制剂室',2000.00000000,18.63000000,0.00000000,18.63000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(58,'Z00058','阴阳和口服液','每支装10ml','委托加工','10ml/支*10支/盒','湘药制字Z20060102','补肾壮阳、填精益髓。用于肾阳虚所致性欲减退、精少不育、腰膝无力等。','以上十四味，鹿角胶用水烊化成40%膏液，备用。海马粉碎成粗粉，加50%乙醇回流提取二次，每次2小时，合并提取液，滤过，滤液备用。其余菟丝子等十二味加水煎煮三次，第一次2小时，第二次1.5小时，第三次1小时，合并煎液，滤过，滤液浓缩至相对密度为1.20(40℃)的清膏，加乙醇使溶液含醇量达65%,静置24小时，取上清液滤过，滤液备用；滤渣用90%乙醇约3000ml分两次洗涤，滤过，合并上述滤液与海马提取液，回收乙醇，浓缩至相对密度为1.15(40℃)的清膏，加入蔗糖170g和苯甲酸钠1.5g,煮沸30分钟，滤过，加入鹿角胶膏液，搅匀，加水至1000ml,搅匀，滤过，灌封，灭菌，即得。','祁阳市中医医院','口服液',NULL,'耒阳制剂室',333.00000000,55.00000000,0.00000000,55.00000000,1,1,35,'2025-10-22 15:16:53','2026-03-24 08:49:01',0,0),(59,'Z00059','骨科补肾口服液','10ml/支*10支/盒','委托加工','每支装10ml','湘药制字Z20060103','益气养血，补益肝肾。用于骨折伤筋之后期证属气血不足者。','以上十三味，龟甲胶、鹿角胶用水烊化成40%的胶液(约350ml);当归、白术、川芎加水蒸馏提取芳香水，收集蒸馏液约400ml,蒸馏后的水溶液另器保存；药渣与其余制何首乌等八味加水煎煮三次，第一次2小时，第二次1.5小时，第三次1小时，合并煎液，滤过，滤液与上述蒸馏后的水溶液合并，浓缩至相对密度为1.20(40℃)的浸膏，加乙醇调至含醇量达60%~70%,静置24小时，取上清液滤过，滤渣用90%乙醇3000ml洗涤两次，滤过，合并滤液，滤液回收乙醇，浓缩至相对密度为1.15(40℃)的浸膏，加入蔗糖170g和苯甲酸钠1.5g,煮沸，滤过，加入上述胶液及芳香水，加水至1000ml,搅匀，静置，滤过，灌封，灭菌，即得。','祁阳市中医医院','口服液',NULL,'耒阳制剂室',5000.00000000,36.23400000,0.00000000,36.23400000,1,1,35,'2025-10-22 15:16:53','2026-03-24 08:49:01',0,0),(60,'Z00060','龟甲劲骨丸','每12丸重1g','自主加工','每瓶装60g*1瓶/盒','湘药制备字Z20230799000','补肝肾，强筋骨。用于骨瘘（骨质疏松）引起的骨折、骨痛、骨关节炎，以及预防更年期骨质疏松见上述证候者。','以上十六味，山药、茯苓、紫河车粉碎成细粉，备用。其余醋龟甲等十三味，加水煎煮两次，第一次1.5小时，第二次1小时，合并煎液，滤过，滤液浓缩至相对密度为1.30-1.35（60℃）的稠膏，加入上述细粉及糊精适量，混匀，制丸，干燥，打光，制成1000g,即得。','新邵县中医医院','丸剂',NULL,'新邵制剂室',1000.00000000,0.00000000,0.00000000,0.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(61,'Z00061','积雪草除湿膏','每支装15g','自主加工','每支装15g*1支/盒','湘药制备字 Z20230791000','祛风除湿，活血止痛。用于风寒湿痹所致风湿痛、关节痛、腰痛、坐骨神经痛、肌肉酸痛等。类风湿性关节炎、风湿性关节炎、腰椎尖盘突出、颈神经根炎、软组织挫伤见上述证候者。','以上十九味，除樟脑、薄荷脑、冰片粉碎成细粉，备用；其余威灵仙等十六味，加水煎煮两次，第一次2小时，第二次1.5小时，滤过，合并滤液，滤液浓缩至相对密度为1.20-1.25（60℃）的稠膏，备用；取凡士林及羊毛脂加热熔融，在50℃-60℃加入上述稠膏、樟脑、薄荷脑、冰片细粉，搅匀至半凝固状，制成1000g,即得。','新邵县中医医院','软膏剂',NULL,'新邵制剂室',0.00000000,0.00000000,0.00000000,0.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(62,'Z00062','颈痛康丸','每12丸重1g','自主加工','每瓶装60g*1瓶/盒','湘药制备字 Z20230758000','益气血、补肝肾、壮筋骨、舒筋通络。用于气血亏虚，肝肾不足，脉络瘀阻所致头痛、头晕、颈项疼痛、活动不利，酸软乏力，肢端麻木，颈椎病见上述证候者。','以上十七味，烫骨碎补、白芍、醋延胡索、红花粉碎成细粉，备用：其余黄芪等十三味，加水煎煮两次，第一次2.0小时，第二1.5小时，合并煎液，滤过，滤液浓缩至相对密度为1.30~1.35(60℃)的稠膏，加入上述细粉及糊精适量，混匀，制丸，干燥，打光，制成1000g，即得。','新邵县中医医院','丸剂',NULL,'新邵制剂室',2000.00000000,0.00000000,0.00000000,72.51000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(63,'Z00063','芪胶补血膏','每袋装20g','自主加工','每袋装20g*15袋/盒','湘药制备字Z20230789000','益所补血，养阴健脾。用于气血两虚型贫血所致面色无华，少气懒言，术后贫血见上述证候者。','以上九味，阿胶粉碎成最粗粉；其余熟地黄等八味，加水煎煮两次，第一次2.0小时，第二次1.5小时，合并煎液，滤过，滤液浓缩至相对密度1.20-1.25（60℃）的稠膏，加入阿胶最粗粉、蜂蜜及苯甲酸适量，混匀，浓缩至规定的相对密度，制成约1000g,即得。','新邵县中医医院','滋膏剂',NULL,'新邵制剂室',500.00000000,0.00000000,0.00000000,0.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(64,'Z00064','膝骨痹康丸','每12丸重1g','自主加工','每瓶装60g*1瓶/盒','湘药制备字 Z20230757000','益气血，补肝肾、化瘀滞、止痹痛。用于气血不足，肝肾亏虚，瘀湿阻滞所致膝关节疼痛，肿胀，活动不利、瘘弱无力，膝骨性关节炎见上述证候者。','以上十七味，烫骨碎补、续断、红花、白芍粉碎成细粉，备用：其余黄芪等十三味加水煎煮两次，第一次2.0小时，第二1.5小时，合并煎液，滤过，滤液浓缩至相对密度为1.30～1.35(60℃)的稠膏，加入上述细粉及糊精适量，混匀，制丸，干燥，打光，制成1000g，即得。','新邵县中医医院','丸剂',NULL,'新邵制剂室',2000.00000000,0.00000000,0.00000000,56.54000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(65,'Z00065','消肿止痛软膏','每支装20g','自主加工','每支装20g*1支/盒','湘药制备字 Z20230790000','活血化瘀、消肿止痛。用于血瘀气滞所致局部肿胀，跌打损伤、骨折、脱臼、伤筋初期见上述证候者。','以上十三味，冰片研磨成细粉，蒲黄，过筛，备用；其余红花等十一味，加水煎煮两次，第一次1.5小时，第二次1.0小时，滤过，合并滤液，滤液浓缩至相对密度为1.20-1.25（60℃）的稠膏，备用；取凡士林、羊毛脂加热熔融，在50℃-60℃左右加入上述稠膏、冰片细粉、蒲黄，搅匀，制成1000g,即得。','新邵县中医医院','软膏剂',NULL,'新邵制剂室',1000.00000000,0.00000000,0.00000000,0.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(66,'Z00066','胸伤康丸','每12丸重1g','自主加工','每瓶装60g*1瓶/盒','湘药制备字 Z20230755000','行气止痛，活血化瘀。用于气滞血瘀所致胸痛、痛有定处、局部青紫、肿胀，胸部损伤见上述证候者。','以上十四味，郁金、醋延胡索、红花、赤芍、桔梗粉碎成细粉，过筛，备用：其余枳壳等九味加水煎煮两次，第一次煎煮2.0小时，第二次煎煮1.5小时，合并煎液，滤过，滤液浓缩至相对密度为1.30～1.35(60℃)的稠膏，加入上述细粉及糊精适量，混匀，制丸，干燥，打光，制成1000g，即得。','新邵县中医医院','丸剂',NULL,'新邵制剂室',2000.00000000,0.00000000,0.00000000,56.79000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(67,'Z00067','腰痹康丸','每13丸重1g','自主加工','每瓶装60g*1瓶/盒','湘药制备字 Z20230792000','益气血，补肝肾、化瘀血、止痹痛。用于肝肾气血亏虚、脉络闭阻所致的腰腿疼痛、下肢麻木疼痛、腰膝酸软、四肢无力、乱动不利。','以上十三味，续断、烫骨碎补粉碎成细粉，备用。其余黄芪等十一味，加水煎煮两次，第一次2.0小时，第二1.5小时，合并煎液，滤过，滤液浓缩至相对密度为1.30～1.35(65℃)的稠膏，加入上述细粉及糊精适量，混匀，制丸，干燥，打光，制成1000g，即得。','新邵县中医医院','丸剂',NULL,'新邵制剂室',2000.00000000,0.00000000,0.00000000,56.54000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(68,'Z00068','固肺丸','120g/瓶','委托加工','120g/瓶','湘药制字Z20080665','补益肺气，止咳平喘。用于慢性支气管炎、肺气肿、肺痨喘咳证属肺明气虚者。','以上十四味，粉碎成细粉，过筛，混匀。每100g细粉加炼蜜80～100g制成小蜜丸，即得。','安化县中医医院','丸剂',NULL,'新邵制剂室',1800.00000000,57.90200000,68.12000000,40.87000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(69,'Z00069','蠲痹止痛丸','120g/瓶','委托加工','120g/瓶','湘药制备字Z20200317001','祛风除湿，活血止痛，滋补肝肾。主治肝肾不足，气血两虚的痹症，症见腰膝关节疼痛，肢节屈伸不利，或麻木不仁，畏寒喜温，肢节重着，心悸气短，舌淡苔白，脉细弱。用于风寒湿痹，伤筋骨折的中晚期治疗。祛风除湿，活血止痛，滋补肝肾。主治肝肾不足，气血两虚的痹症，症见腰膝关节疼痛，肢节屈伸不利，或麻木不仁，畏寒喜温，肢节重着，心悸气短，舌淡苔白，脉细弱。用于风寒湿痹，伤筋骨折的中晚期治疗。','以上二十二味，粉碎成细粉，过筛，混匀。每100g粉末加炼蜜60～90g，制成小蜜丸，即得。','安化县中医医院','丸剂',NULL,'新邵制剂室',2400.00000000,45.56900000,53.61000000,32.17000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(70,'Z00070','盆炎宁丸','120g/瓶','委托加工','120g/瓶','湘药制备字Z20200319001','清热利湿、祛瘀止痛、收敛止带、活血调经。用于急性盆腔炎、附件炎、子宫内膜炎、经闭痛经、妇女带下等症。','以上二十四味，粉碎成细粉，过筛，混匀。每100g粉末加炼蜜60～90g，制成小蜜丸，即得。','安化县中医医院','丸剂',NULL,'新邵制剂室',600.00000000,38.82000000,45.67000000,27.40000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(71,'Z00071','接骨疗伤丸','120g/瓶','委托加工','120g/瓶','湘药制备字Z20200318001','活血祛瘀、理气止痛、接筋续骨。用于骨折伤筋的初中期。','以上十九味，粉碎成细粉，过筛，混匀。每100g粉末加炼蜜60～90g，制成小蜜丸，即得。','安化县中医医院','丸剂',NULL,'新邵制剂室',1800.00000000,35.30100000,41.53000000,24.92000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(72,'Z00072','玄麦豆桔丸','120g/瓶','委托加工','120g/瓶','湘药制字Z20080662','清咽润喉，化痰利气。用于慢性咽喉炎、扁桃体炎等证属痰热伤阴者。','以上十一味，除硼砂外，其余山豆根等十味粉碎成细粉，备用，硼砂研成细粉，按等量递增法与上述细粉混匀，每100g细粉加炼蜜80～100g制成小蜜丸，即得。','安化县中医医院','丸剂',NULL,'新邵制剂室',1200.00000000,42.05000000,49.47000000,29.68000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(73,'Z00073','如意二黄散','每袋装30g','委托加工','每盒装1袋','湘药制字Z20080667','活血祛瘀，消肿止痛。用于跌打损伤、血瘀气滞所致筋骨肿痛。','以上二十七味，血竭、生马钱子、三七分别粉碎成最细粉，备用。其余栀子等二十四味混合粉碎成最细粉，与血竭等三味最细粉用等量递增法混匀，即得。','安化县中医医院','散剂',NULL,'新邵制剂室',8000.00000000,15.30000000,18.00000000,10.80000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(74,'Z00074','康龙胶囊','0.3g/粒*60粒/瓶','委托加工','每粒装0.3g','湘药制字Z20080886','化瘀解毒，软坚散结。用于肺癌、肝癌等恶性肿瘤证属瘀毒内结者的辅助治疗。','以上九味，取大黄30g、制马钱子、三七粉碎成细粉，备用；土鳖虫加75%乙醇回流提取3小时，滤过，药渣备用；滤液回收乙醇，浓缩至相对密度为1.30（60℃）的浸膏，备用；炮山甲粉碎成粗粉，布包，浸泡0.5小时，与剩余大黄、炮附片、甘草及土鳖虫醇提后的药渣加水煎煮两次，第一次1.5小时；第二次1小时，滤过，合并滤液减压浓缩至相对密度为1.30（60℃）的浸膏，加入上述浸膏，干燥，粉碎成细粉，加入上述备用细粉及熊胆粉、雄黄粉，混匀，装入胶囊，制成1000粒，即得。','长沙市岳麓区东雅门诊部','胶囊剂',NULL,'邵阳制剂室',600.00000000,300.00000000,0.00000000,300.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(75,'Z00075','榆炭烧伤软膏','50g/瓶*10瓶/盒','委托加工','50g/瓶*10瓶/盒','','','','永州金凤烧伤专科医院','软膏剂',NULL,'新邵制剂室',3000.00000000,28.98000000,0.00000000,28.98000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(76,'Z00076','芪参调经颗粒','8g/袋*6袋/盒','委托加工','每袋装 8g','湘药制备字Z20220681000','补气养血，祛瘀调经。用于久病体虚或气血两虚所致神疲乏力、面色无华、失眠多梦、月经量少色淡、月经淋漓不尽、经期延长等，以及女性月经不调或更年期综合症见上述证候者。','以上十一味，阿胶粉碎成细粉，备用；余下药味加水煎煮两次，第一次1.5小时，第二次1小时，滤过，合并滤过，浓缩至相对密度约为1.30～1.35（60℃）的稠膏，干燥，粉碎，加入阿胶细粉，糊精及甜菊糖苷适量，混匀，制粒，干燥，制成1000g，即得。','岳阳市中心医院','颗粒剂',NULL,'新邵制剂室',1000.00000000,63.89000000,0.00000000,51.11200000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(77,'Z00077','胶芪养血膏','15g/袋*15袋/盒','委托加工','每袋装15g','湘药制备字Z20220697000','补气养血，祛瘀调经。用于久病体虚或女性气血两虚所致神疲乏力，面色无华，月经量少，色淡，或月经淋漓不尽，经期延长等见上述证候者。','以上十二味，阿胶粉碎成最粗粉；其余黄芪等十一味，加水煎煮两次，第一次2.0小时，第二次1.5小时，合并煎液，滤过，滤液浓缩至相对密度为1.20～1.25（60℃）的清膏，加入阿胶最粗粉、蜂蜜及苯甲酸钠适量，混匀，浓缩至规定的相对密度，制成约1000g，即得。','安乡县人民医院','滋膏剂',NULL,'新邵制剂室',500.00000000,70.64000000,0.00000000,70.64000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(78,'Z00078','荆杏清热化痰合剂','200ml/瓶','委托加工','每瓶装200ml','湘药制备字Z20220698000','疏风散寒，清热化痰。用于小儿外感风寒化热引起的咳嗽，咯痰，痰黄、咽部红肿、发热等症状。上呼吸道感染或急性支气管炎见上述症状者。','以上十三味，加水煎煮两次，第一次2.0小时，第二次1.5小时，合并煎液，滤过，滤液浓缩至相对密度为1.05～1.10（60℃）的清膏，滤过，滤液加入三氯蔗糖、苯甲酸钠适量，搅匀，加水至约1000ml，即得。','安乡县人民医院','合剂',NULL,'邵阳制剂室',2000.00000000,16.03000000,0.00000000,16.03000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(79,'Z00079','夏柴散乳合剂','200ml/瓶','委托加工','每瓶装200ml','湘药制备字Z20220695000','疏肝解郁，软坚散结。用于肝郁气滞、痰瘀互结所致乳房胀满疼痛，乳腺小叶增生，囊性增生见上述证候者。','以上十二味，加水煎煮两次，第一次2小时，第二次1.5小时，合并煎液，滤过，滤液浓缩至相对密度为1.10～1.15（60℃）的清膏，滤过，滤液加入三氯蔗糖、苯甲酸钠适量，搅匀，加水至约1000ml，即得。','安乡县人民医院','合剂',NULL,'邵阳制剂室',1000.00000000,22.46000000,0.00000000,22.46000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(80,'Z00080','伸筋止痛酊','100ml/瓶','委托加工','每瓶装100ml','湘药制备字Z20230719000','活血通络，散寒止痛。用于颈椎、腰椎间盘、膝关节等骨质增生引起的疼痛及功能性障碍，软组织损伤、扭伤等引起的肿胀、疼痛、肢体麻木。','以上十二味，粉碎成粗粉，用70%乙醇浸渍两次，第一次浸渍5日，第二次浸渍1日，滤过，合并滤液，用70%乙醇调整成1000ml，搅匀，即得。','安乡县人民医院','酊剂',NULL,'新邵制剂室',1000.00000000,8.54000000,33.42000000,8.54000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(81,'Z00081','安神祛白丸','10g/袋*6袋/盒','委托加工','每袋装10g','湘药制备字Z20220701000','养心安神，活血通络，祛白消斑。用于心肾不交，瘀血阻络所致的白驳风，症见白斑散在分布，边界清楚，位置较固定，色泽苍白，伴心悸、失眠；白癜风见上述证候者。','以上十一味，粉碎成细粉，过筛，灭菌，混匀，加淀粉浆适量，制丸，干燥，制成约1000g,即得。','长沙中科皮肤病医院','丸剂',NULL,'新邵制剂室',4000.00000000,18.20000000,0.00000000,18.20000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(82,'Z00082','祛风活血消白丸','10g/袋*6袋/盒','委托加工','每袋装10g','湘药制备字Z20220702000','活血行滞，祛风解毒，祛白消斑。用于经络阻隔、气血不和所致的白驳风，症见白斑散在不对称，部位较固定，边界较清楚，皮色苍白；白癜风见上述证候者。','以上九味，粉碎成细粉，过筛，灭菌，混匀，加淀粉浆适量，制丸，干燥，制成约1000g,即得。','长沙中科皮肤病医院','丸剂',NULL,'新邵制剂室',4000.00000000,15.10000000,0.00000000,15.10000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(83,'Z00083','健脾消白颗粒','5g/袋*6袋/盒','委托加工','每袋装5g','湘药制备字Z20220699000','益气补血，健脾和胃，祛白消斑。用于气血不足，脾胃虚弱所致的白驳风，症见白斑色萎黄，多有对称，边界欠清，伴神疲乏力、纳差、腹胀、便溏；白癜风见上述证候者。','\"以上十二味，加水浸泡0.5小时，煎煮二次，第一次1.5小时，第二次1 小时，合并煎液，滤过，滤液浓缩至相对密度为1.20～1.35(60℃)的浸膏，干燥，粉碎成细粉，加糊精适量，混匀，以85%乙醇制粒，干燥，制成1000g,即得。\"','长沙中科皮肤病医院','颗粒剂',NULL,'新邵制剂室',5000.00000000,17.20000000,0.00000000,17.20000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(84,'Z00084','祛白乌发合剂','100ml/瓶','委托加工','每瓶装100ml','湘药制备字Z20220700000','滋补肝肾，乌须黑发，祛白消斑，养血润肤。用于肝肾亏虚所致的白驳风，症见白斑局限或泛发，多有对称，边界楚，色泽乳白，白斑内毛发可变白，病程较久，伴头晕耳鸣、失眠健忘、腰膝酸软；白癜风见上述证候者。','以上九味，加水浸泡0.5小时，煎煮二次，第一次1.5小时，第二次1小时，合并煎液，滤过，滤液浓缩至1000ml,加入苯甲酸钠3g,搅匀，灌装，即得。','长沙中科皮肤病医院','合剂',NULL,'邵阳制剂室',3000.00000000,6.82000000,0.00000000,6.82000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(85,'Z00085','苦参黄柏洗液','250ml/瓶','委托加工','每瓶装250ml','湘药制备字Z20230772000','\"清热解毒，燥湿祛风，杀虫止痒。用于湿热下注所致的阴痒、带下病和 湿热蕴肤所致的湿疮，症见带下量多、色黄味臭、阴部瘙痒，或皮肤红斑、丘疹、瘙痒；阴道炎、湿疹见上述证候者。\"','以上十二味，枯矾粉碎成细粉；其余苦参等十一味，加水浸泡0.5小时，煎煮二次，第一次1.5小时，第二次1小时，合并煎液，加入枯矾细粉，搅匀，滤过，滤液浓缩至1000ml,加入苯甲酸钠3g,搅匀，灌装，即得。','益阳市第一中医医院','洗剂',NULL,'邵阳制剂室',500.00000000,21.00000000,44.50000000,21.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(86,'Z00086','苍耳鼻炎颗粒','8g/袋*9袋/盒','委托加工','每袋装8g','湘药制备字Z20230731000','益气固表，祛风通窍。用于肺气不足，风邪外袭所致的鼻窒、鼻勉，症见鼻塞、鼻痒、喷嚏、流清涕；慢性鼻炎、过敏性鼻炎见上述证候者。','\"以上十味，加水浸泡0.5小时，煎煮二次，第一次1.5小时，第二次1小时，合并煎液，滤过，滤液浓缩至相对密度为1.20～1.35(60℃)的浸膏，干燥，粉碎 成细粉，加蔗糖适量，混匀，以85%乙醇制粒，干燥，制成约1000g,即得。\"','澧县中医医院','颗粒剂',NULL,'新邵制剂室',2000.00000000,42.95000000,0.00000000,42.95000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(87,'Z00087','扶正消癥丸','6g/袋*9袋/盒','委托加工','每袋装6g','湘药制备字Z20230733000','益气扶正，解毒消癥。用于正气亏虚，瘀毒内阻所致的肿瘤，症见局部肿块疼痛、痛有定处、倦怠乏力、纳差、舌质紫黯、脉细涩；癌症见上述证候者。','以上十五味，粉碎成细粉，过筛，灭菌，混匀，加淀粉浆适量，制丸，干燥，制成约1000g,即得。','澧县中医医院','丸剂',NULL,'新邵制剂室',4000.00000000,19.03000000,0.00000000,19.03000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(88,'Z00088','丹参养心丸','每袋装8g','委托加工','每盒装9袋','湘药制备字Z20230761000','益气养阴，行气止痛，化痰祛瘀。用于气阴两虚，瘀血阻脉所致的胸痹、心悸，症见胸闷心痛、心悸气短、倦怠汗出、咽喉干燥；冠心病心绞痛、心律失常见上述证候者。','以上十五味，粉碎成细粉，过筛，灭菌，混匀，加水适量，制丸，干燥，制成约1000g,即得。','澧县中医医院','丸剂',NULL,'新邵制剂室',2000.00000000,28.25000000,0.00000000,28.25000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(89,'Z00089','强肾壮骨丸','每11丸重1g','委托加工','每瓶装120g','湘药制备字Z20230745000','具有补益肝肾，强筋壮骨，活络止痛的功效，用于肝肾不足、经络痹阻所致腰酸膝软、腰背或四肢关节疼痛、畏寒肢冷或抽筋、下肢无力、夜尿频多，骨痿、骨折后期、退行性骨关节病见上述证候者。','以上十二味，鹿茸、续断片、烫狗脊粉碎成细粉，备用。其余熟地黄等九味，加水煎煮两次，第一次2.0小时，第二次1.5小时，合并煎液，滤过，滤液浓缩至相对密度为1.30~1.35（60℃）的稠膏，加入上述细粉及糊精适量，混匀，制丸，干燥，打光，制成1000g，即得。','安乡县人民医院','丸剂',NULL,'新邵制剂室',1000.00000000,68.21000000,0.00000000,68.21000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(90,'Z00090','地黄明目颗粒','6g/袋*10袋/盒','委托加工','每袋装6g','湘药制备字Z20230753000','补肝益肾，养血明目。用于肝肾亏虚证所致的视物昏朦不清，自视眼前有带色阴影遮隔或视物变形、畏光或有头晕、耳鸣、睡眠不佳及眼底血管硬化、渗出、水肿或有新生血管出血等糖尿病性视网膜病变、高血压性视网膜病变，及各类视网膜病变见上述证候者。','以上十二味，加水煎煮两次，第一次1.5小时，第二次1.0小时，合并煎液，滤过，滤液浓缩至相对密度约为1.25～1.30（60℃）的稠膏，干燥，粉碎，加入糊精、三氯蔗糖适量，混匀，制粒，干燥，制成1000g，即得。','津市市中医医院','颗粒剂',NULL,'新邵制剂室',2000.00000000,29.67500000,59.35000000,29.67500000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(91,'Z00091','益肾明目颗粒','8g/袋*10袋/盒','委托加工','每袋装8g','湘药制备字Z20230754000','滋阴益肾，健脾养血，生津明目。用于肝肾阴亏所致眩晕耳鸣，羞明畏光，迎风流泪，视物昏花、眼前阴影飘动等。慢性前葡萄膜炎、黄斑水肿、早期老年黄斑变性、玻璃体浑浊等见上述症状者。','以上二十味，加水煎煮二次，第一次煎煮2.0小时，第二次煎煮1.5小时，合并煎液，滤过，浓缩至相对密度约为1.25～1.30（60℃）的稠膏，干燥，粉碎，加入糊精、三氯蔗糖适量，混匀，制粒，干燥，制成1000g，即得。','津市市中医医院','颗粒剂',NULL,'新邵制剂室',2000.00000000,34.24000000,68.48000000,34.24000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(92,'Z00092','祛湿通络丸','8g/袋*9袋/盒','委托加工','每袋装8g','湘药制备字Z20230759001','祛风除湿，通络止痛。用于外感风寒湿邪，经络受阻，气血不通所致的头晕目眩、颈腰部疼痛、板滞、肌肉痉挛，甚至僵硬、转动困难、上下肢肢体麻木疼痛、关节屈曲不利等，颈椎病、腰椎病、肩周炎及各类骨关节疾病见上述证候者。','以上二十五味，粉碎成细粉，混匀，加入糊精适量，混匀，制丸，干燥，打光，制成1000g，即得。','汉寿县中医医院','丸剂',NULL,'新邵制剂室',3000.00000000,42.26000000,44.37000000,35.92100000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(93,'Z00093','骨折愈伤丸','7g/袋*9袋/盒','委托加工','7g/袋','湘药制备字Z20210455000','舒筋活络、活血散瘀。用于急性软组织损伤气滞血瘀证。','以上九味，红花50℃干燥，单独粉碎成细粉，灭菌。三七破碎后，与土鳖虫等余药混合，60℃干燥，粉碎成细粉，过100目筛，灭菌，再加入红花细粉混合均匀，每100g药粉加炼蜜50~70g与适量的水制成水蜜丸，50℃干燥，约制成1000g，分装，即得。','湘阴县中医院','丸剂',NULL,'新邵制剂室',1500.00000000,39.83000000,41.22000000,22.85000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(94,'Z00094','黄消降浊丸','8g/袋*9袋/盒','委托加工','8g/袋','湘药制备字Z20210456000','通腑泄浊，解毒消滞。用于慢性肾功能衰竭湿热内停证。','以上十味，红花50℃干燥，粉碎成细粉，灭菌。大黄、桃仁等余药60℃干燥，粉碎成细粉，灭菌，与红花灭菌后药粉混合均匀，每100g药粉加炼蜜50~70g与适量的水制成水蜜丸，50℃干燥，约制成1000g，分装，即得。','湘阴县中医院','丸剂',NULL,'新邵制剂室',1500.00000000,42.17000000,0.00000000,21.90000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(95,'Z00095','天麻解眩合剂','250ml/瓶','委托加工','每瓶装250ml','湘药制备字Z20230775000','燥湿化痰，平肝熄风。用于痰涎内停、虚风上扰所致的头晕目眩、头痛如裂、恶心烦闷、身体沉重、四肢困倦等，高血压、癫痫、腔隙性脑梗塞、美尼尔综合征见上述症状者。','以上十八味，加水煎煮两次，第一次1.5小时，第二次1小时，合并煎液，滤过，浓缩至相对密度约1.05～1.10（60℃）的清膏，滤过，滤液加入三氯蔗糖、苯甲酸钠适量，加水至1000ml，搅匀，分装，即得。','汉寿县中医医院','合剂',NULL,'邵阳制剂室',1500.00000000,53.65000000,56.33000000,45.60300000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(96,'Z00096','葛根桑椹合剂','50ml/瓶*6瓶/盒','委托加工','每瓶装50ml','湘药制备字Z20230777000','滋补肝肾，养血安神，生津止渴，润肠通便。用于肝肾不足、气血亏虚所致的失眠多梦、五心烦热、神疲乏力、咽干口燥、便秘，及糖尿病患者见上述证候者。','以上九味，加水煎煮两次，第一次2小时，第二次1.5小时，合并煎液，滤过，滤液浓缩至相对密度为1.05～1.10（60℃）的清膏，滤过，取滤液，加入苯甲酸钠适量，搅匀，加水至1000ml，即得。','湘潭糖尿病医院','合剂',NULL,'邵阳制剂室',600.00000000,39.90000000,0.00000000,39.90000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(97,'Z00097','骨刺散','25g/袋','委托加工','每袋装25g','湘药制备字Z20190114000','活血化瘀，补肾壮骨，通络止痛。用于治疗颈椎、腰椎、四肢关节骨质增生','以上九味，除樟脑外，其余骨碎补等八味粉碎成细粉备用；将樟脑粉碎成细粉，与上述细粉配研，过筛，混匀，分装，即得。','湘乡起蛟中医医院','散剂',NULL,'新邵制剂室',5000.00000000,41.73900000,48.00000000,17.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(98,'Z00098','椎灵丸','待定','委托加工','','','','','汉寿县中医医院','丸剂',NULL,'新邵制剂室',0.00000000,0.00000000,0.00000000,0.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(99,'Z00099','痔疮内消丸','120g/瓶','委托加工','每瓶装120g','湘药制字Z20090889','清热除湿，凉血止血，润肠通便。用于外痔，内痔，混合痔肿胀，便前后出血，肛裂，脱肛，便秘等证属湿热或燥热者。','以上十二味，粉碎成细粉，混匀。每100g粉末加炼蜜50～80g,制成小蜜丸，即得。','祁阳市中医医院','丸剂',NULL,'新邵制剂室',500.00000000,26.62200000,0.00000000,26.62200000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(100,'Z00100','滴菌净洗剂','150ml/瓶','委托加工','每瓶装150ml','湘药制字Z20090932','清热解毒，祛风止痒，燥湿除带。用于妇女湿热下注所致带下量多，色黄或如豆渣状。','以上十一味，蛇床子、苍术、花椒、石菖蒲加水蒸馏提取芳香水600ml,备用；蒸馏后的水溶液另器收集；药渣与其余黄柏等七味，加水煎煮三次，第一次2小时，第二次1.5小时，第三次1小时，合并煎液，滤过，滤液与上述蒸馏后的水溶液合并，浓缩至相对密度约为1.15(40℃)的浸膏，加乙醇使含醇量达约60%,静置24小时，取上清液滤过；滤渣用90%乙醇3000ml分2次洗涤，滤过，合并滤液，回收乙醇并浓缩至相对密度约1.10(40℃)的浸膏，加入上述芳香水，加水至1000ml,搅匀，静置，滤过，即得。','祁阳市中医医院','洗剂',NULL,'邵阳制剂室',5000.00000000,21.67800000,36.13000000,21.67800000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(101,'Z00101','红花止痛膏','6g/贴x2贴/袋x3袋/盒','委托加工','每贴净重6g','湘药制备字Z20230832000','活血行滞，消肿止痛。用于瘀血阻络、气血凝结所致关节疼痛、肿胀、关节活动不利，跌打损伤、骨折、颈腰椎疾病见上述证候者。','以上十八味，龙血竭、醋乳香、醋没药、三七、蒲黄粉碎成细粉，备用；除红花、烫骨碎补、降香外，其余续断片等十味，与麻油1000g置锅内浸渍24小时，炸至药材表面焦黄色，再加入红花、烫骨碎补、降香，炸至药材内部焦褐色，弃渣，滤过，炼油至滴水成珠。加入铅丹320g~400g,搅匀，收膏，浸膏、取膏，用文火熔化，加入上述细粉，搅匀，制成1000g,分摊于无纺布上，即得。','安乡县人民医院','贴膏',NULL,'新邵制剂室',2000.00000000,26.82000000,0.00000000,26.82000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(102,'Z00102','九味通络颗粒','10g/袋*9袋/盒','委托加工','10g/袋','湘药制备字Z20230746000','活血祛瘀、行气止痛。用于痹症之气滞血瘀证，症见腰腿关节痛、疼痛日久，麻木、伸屈不利或全身疼痛；腰椎间盘突出症、退行性骨关节病见上证候者。','\"以上九味，三七粉碎成细粉，灭菌，备用。当归等八味，加水煎煮两次，第一次加10倍量水，煎煮2小时，滤过。第二次加8倍量水，煎煮1.5小时，滤过。滤液减压浓缩成相对密度为1.20~1.2（60℃） 的稠膏，真空干燥得干膏，粉碎，加入三七粉、甜菊糖苷3g和糊精适量，混匀，制粒，制成1000g，即得。\"','湘乡起蛟中医医院','颗粒剂',NULL,'新邵制剂室',2000.00000000,82.60900000,95.00000000,41.70000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(103,'Z00103','川参浓缩丸','8g/袋*9袋/盒','委托加工','8g/袋','湘药制备字Z20230744000','益气养血，温中散寒。用于属气血亏虚，血瘀寒凝证者，症见头晕目眩，气短懒言，神疲乏力，形寒肢冷，腰膝酸软；慢性腹痛、痛经、月经紊乱见上述证候者。','以上十四味，当归、川芎、醋香附、鹿角霜及醋延胡索粉碎成细粉，灭菌，阿胶单独粉碎。其余党参等八味加水煎煮两次，第一次加10倍量水，煎煮2.0小时，滤过；第二次加8倍量水，煎煮1.5小时，滤过。滤液浓缩成相对密度为1.30～1.35(60℃)的稠膏，与灭菌后的细粉、阿胶粉混匀，加入适量75%乙醇，制丸、干燥、制成1000g。','湘乡起蛟中医医院','丸剂',NULL,'新邵制剂室',1000.00000000,59.13000000,68.00000000,27.60000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(104,'Z00104','胆豆丸','3g/袋*9袋/盒','委托加工','每袋装3g','湘药制备字Z20210432000','疏肝利胆，清热解毒，化瘀止痛。用于肝胆湿热蕴结所致的胁痛、胆胀，症见胁肋胀痛、发热、口苦、尿黄、大便不通；急、慢性胆囊炎，胆石症见上述证候者。','以上三味，粉碎成细粉，过筛，灭菌，混匀，加水适量，塑制法制丸，干燥，分装，即得。','临澧县中医医院','丸剂',NULL,'新邵制剂室',2000.00000000,29.16000000,48.60000000,29.16000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(105,'Z00105','蚁蚣丸','6g/袋*9袋','委托加工','每袋装6g','湘药制备字Z20210434000','益气活血，祛风除湿，通经活络，补肾助阳。用于气血不足，肝肾两亏，风湿瘀阻所致的痹病，症见关节疼痛、屈伸不利、四肢麻木、腰膝酸软；风湿性关节炎、类风湿关节炎、坐骨神经痛见上述证候者。亦用于肾阳不足所致的阳痿，症见阳事不举、勃起不坚、腰酸乏力；性功能衰退见上述证候者。','以上四味，粉碎成细粉，过筛，灭菌，混匀，加水适量，塑制法制丸，干燥，分装，即得。','临澧县中医医院','丸剂',NULL,'新邵制剂室',2000.00000000,31.68000000,0.00000000,31.68000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(106,'Z00106','昆藻散结丸','10g/袋*9袋/盒','委托加工','每袋装10g','湘药制备字Z20210464000','软坚散结，化痰祛瘀。用于痰瘀互结所致的脑肿瘤，症见头痛、视物模糊、呕吐、眩晕。','以上二十二味，粉碎成细粉，过筛，灭菌，混匀，加水适量，塑制法制丸，干燥，分装，即得。','临澧县中医医院','丸剂',NULL,'新邵制剂室',300.00000000,126.48000000,0.00000000,126.48000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(107,'Z00107','补骨丸','120g/瓶','委托加工','每瓶120g','湘药制备字Z20180019000','补肾生髓。用于骨折后期迁延不愈证属肾虚髓亏者。','以上十四味，粉碎成细粉，过筛，混匀。每100g粉末加80g炼蜜制成小蜜丸，干燥，即得。','常宁市中医医院','丸剂',NULL,'益阳制剂室',2000.00000000,21.00000000,0.00000000,21.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(108,'Z00108','舒筋接骨丸','120g/瓶','委托加工','每瓶120g','湘药制备字Z20180017000','补肾活血，续筋接骨。用于骨折中期证属肾虚血瘀者。','以上十五味，粉碎成细粉，过筛，混匀，每100g粉末加炼蜜80g,制成小蜜丸，即得。','常宁市中医医院','丸剂',NULL,'益阳制剂室',2000.00000000,23.00000000,0.00000000,23.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(109,'Z00109','新伤丸','100g/瓶','委托加工','每瓶装100g','湘药制备字Z20210500000','活血祛瘀，消肿止痛。用于跌打损伤早期瘀血肿痛。','以上十六味，粉碎成细粉，过筛，混匀，用水泛丸，干燥，制成1000g,即得。','常宁市中医医院','丸剂',NULL,'益阳制剂室',2000.00000000,30.00000000,0.00000000,30.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(110,'Z00110','培元固本口服液','每支装10ml','委托加工','10ml/支*10支/盒','湘药制字Z20060101','温肾培元，气血双补。主治肾元亏虚，气血不足所致面色萎黄，神疲乏力，腰膝酸软，头昏眼花，畏寒肢冷，性功能减退等症，以及慢性消耗性疾病有上述见症者。','以上十四味，红参粉碎成粗粉，照流浸膏剂与浸膏剂项下的方法(中国药典2015年版四部通则0189),用70%乙醇作溶剂，浸渍24小时后，以每分钟1～3ml的速度缓缓渗漉，收集渗漉液50ml;药渣与其余熟地黄等十三味加水煎煮二次，第一次2小时，第二次1.5小时，合并煎液，滤过，滤液加入红参渗漉液，静置12小时，取上清液浓缩至相对密度约为1.06(40℃)的浸膏。加入蜂蜜200g、苯甲酸钠2.5g,煮沸使溶解，加水至1000ml,搅匀，冷藏24～48小时，取上清液，灌封，灭菌，即得。','常宁市中医医院','口服液',NULL,'耒阳制剂室',2500.00000000,15.00000000,0.00000000,15.00000000,1,1,35,'2025-10-22 15:16:53','2026-03-24 08:49:01',0,0),(111,'Z00111','桃红消瘀酊','60ml/瓶','委托加工','每瓶装60ml','湘药制备字Z20210499000','活血化瘀，通络止痛。用于骨折伤筋早期，气血瘀滞所致肢体肿痛。','以上二十味，粉碎成粗粉，用布袋包裹，用60%乙醇1000ml浸渍40日，每隔3～4日搅拌1次，收集浸出液，压粹药渣，滤液与没出液合并，静置24小时，取上清液，滤过，加60%乙醇至1000ml,即得。','常宁市中医医院','酊剂',NULL,'耒阳制剂室',0.00000000,48.00000000,35.00000000,48.00000000,1,1,1,'2025-10-22 15:16:53','2026-03-24 08:49:01',0,0),(112,'Z00112','益肾养骨膏（膏方）','每袋装20g(每1g相当于饮片约1.58g)','自主加工','每盒装30袋','湘药制备字 Z20230882000','补肝肾， 强筋骨， 益气养血。用于肝肾不足所致骨脆易折、腰背或四肢关节疼痛、肌肉劳损、畏寒吱冷或抽筋等， 以及退行性骨关节病、骨质疏松症见上述症状者。','以上二十味，鹿角胶、龟甲胶粉碎成最粗粉，备用；其余熟地黄等十八味，加水煎煮二次，第一次2小时，第二次1.5小时，合并煎液，滤过，滤液浓缩至相对密度为1.20～1.25（60℃）的清膏，取上述鹿角胶、龟甲胶最粗粉、木糖醇、甜菊糖苷及苯甲酸钠适量，混匀，浓缩至规定的相对密度，制成1000g，即得。','新邵县中医医院','膏方',NULL,'新邵制剂室',120.00000000,0.00000000,350.00000000,0.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(113,'Z00113','化瘀壮骨膏（制剂）','每袋装20g（每1g相当于饮片1.65g）','自主加工','每盒装15袋','湘药制备字Z20241094000','补肾壮骨，活血消肿，促进骨折愈合。用于气滞血瘀所致肿胀、瘀血、疼痛、关节活动不利等，跌打损伤、肌肉劳损、骨折、脱白、骨质疏松见上述证候者。','以上二十三味，阿胶粉碎成最粗粉，备用；其余党参等二十二味，加水煎煮两次，第一次2小时，第二次1.5小时，合并煎液，滤过，滤液浓缩至相对密度为1.25～1.30（60℃）的清膏，取蜂蜜适量加热制成1.28~1.30（60℃）的炼蜜，加入上述清膏、阿胶最粗粉、木糖醇、甜菊糖苷及苯甲酸钠适量，加热使溶化，混匀，浓缩至相对密度1.30～1.35（60℃），制成1000g，即得。','新邵县中医医院','膏方',NULL,'新邵制剂室',240.00000000,0.00000000,410.00000000,0.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(114,'Z00114','益气养心膏（膏方）','每袋装20g','自主加工','每盒装30袋','','','','新邵县中医医院','膏方',NULL,'新邵制剂室',120.00000000,0.00000000,350.00000000,0.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(115,'Z00115','小儿健脾助长膏（膏方）','每袋装20g(相当于中药饮片27.5g)','自主加工','每盒装30袋','湘药制备字Z20230821000','健运消食，益气补虚。用于脾肾亏虚所致长期食欲不振、食积不化、不思进食、面色少华、发育迟缓、身高体重低于同龄儿童、舌质淡、苔薄白、脉缓等，以及小儿消化不良、小儿疳积等见上述症状者。','以上二十一味药，阿胶粉碎成最粗粉，备用；其余党参等二十味，加水煎煮二次，第一次2小时，第二次1.5小时，合并煎液，滤过，滤液浓缩至相对密度为1.20～1.25（60℃）的清膏，取蜂蜜适量加热制成1.28～1.30（60℃）的炼蜜，加入上述清膏、阿胶最粗粉、甜菊糖苷及苯甲酸钠适量，混匀，浓缩至规定的相对密度，制成1000g，即得。','新邵县中医医院','膏方',NULL,'新邵制剂室',120.00000000,0.00000000,320.00000000,0.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(116,'Z00116','青娥膏','20g/支','自主加工','每支20g','','','','邵阳市中医医院','膏方',NULL,'邵阳制剂室',0.00000000,0.00000000,0.00000000,0.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(117,'Z00117','资生膏','20g/支','自主加工','每支20g','','','','邵阳市中医医院','膏方',NULL,'邵阳制剂室',0.00000000,0.00000000,0.00000000,0.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(118,'Z00118','离兑膏','20g/支','自主加工','20g每支','','','','邵阳市中医医院','膏方',NULL,'邵阳制剂室',0.00000000,0.00000000,0.00000000,0.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(119,'Z00119','扶正固本膏','20g/支','自主加工','20g每支','','','','邵阳市中医医院','膏方',NULL,'邵阳制剂室',0.00000000,0.00000000,0.00000000,0.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(120,'Z00120','益肾养巢膏','20g/支','自主加工','20g每支','','','','邵阳市中医医院','膏方',NULL,'邵阳制剂室',0.00000000,0.00000000,0.00000000,0.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(121,'Z00121','扶阳膏','20g/支','自主加工','20g每支','','','','邵阳市中医医院','膏方',NULL,'邵阳制剂室',0.00000000,0.00000000,0.00000000,0.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(122,'Z00122','归脾膏','20g/支','自主加工','20g每支','','','','邵阳市中医医院','膏方',NULL,'邵阳制剂室',0.00000000,0.00000000,0.00000000,0.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(123,'Z00123','补肺益肾汤浓煎液','50ml/袋','自主加工','50ml每袋','','','','邵阳市中医医院','浓煎剂',NULL,'邵阳制剂室',0.00000000,0.00000000,0.00000000,0.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(124,'Z00124','补阳还五汤浓煎液','50ml/袋','自主加工','50ml每袋','','','','邵阳市中医医院','浓煎剂',NULL,'邵阳制剂室',0.00000000,0.00000000,0.00000000,0.00000000,1,1,1,'2025-10-22 15:16:53','2025-10-22 15:16:53',0,0),(125