  `preparation_code` varchar(50) NOT NULL COMMENT '制剂编码',
  `preparation_name` varchar(100) NOT NULL COMMENT '制剂名称',
  `plan_quantity` decimal(20,8) NOT NULL COMMENT '计划数量（批量）',
